ath d=''M218 139h43'' stroke=''%23fff'' stroke-opacity=''.3''/%3E%3Cpath d=''M113 152h42'' stroke=''%23fff'' stroke-opacity=''.4''/%3E%3Cpath d=''M260 160h32'' stroke=''%23fff'' stroke-opacity=''.3''/%3E%3Cpath d=''M314 163h33'' stroke=''%23fff'' stroke-opacity=''.4''/%3E%3Cpath d=''M560 159h23'' stroke=''%23fff'' stroke-opacity=''.3''/%3E%3Cpath d=''M443 152h30'' stroke=''%23fff'' stroke-opacity=''.5''/%3E%3Cpath d=''M231 166h36'' stroke=''%23fff'' stroke-opacity=''.3''/%3E%3Cpath d=''M423 144h42'' stroke=''%23fff'' stroke-opacity=''.5''/%3E%3Crect width=''600'' height=''200'' fill=''url(%23vg)''/%3E%3C/svg%3E', NULL, 420, NULL, NULL, NULL, 'rare', 21537, NULL, '{"name":{"tr":"Buzul Koyu","en":"Glacier Bay","de":"Gletscherbucht","es":"Bahía glaciar","fr":"Baie des glaciers","pt-BR":"Baía glacial","ru":"Ледниковый залив"},"description":{"tr":"Sakin suda yüzen buz kütleleri ve yansıyan turkuaz buzul.","en":"Icebergs floating on still water beneath a turquoise glacier.","de":"Eisberge auf stillem Wasser vor einem türkisfarbenen Gletscher.","es":"Icebergs flotando en aguas quietas bajo un glaciar turquesa.","fr":"Des icebergs sur une eau immobile, sous un glacier turquoise.","pt-BR":"Icebergs boiando em águas calmas sob uma geleira turquesa.","ru":"Айсберги на спокойной воде под бирюзовым ледником."}}'::jsonb, '["shop2","c1"]'::jsonb, NULL),
('s2-voice_tile-gece-limani', 'Night Watch', 'The tile everyone sees in voice channels and calls: a foggy pier, a lighthouse beam and calm waves. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 640, NULL, NULL, 'vt-gece-limani', 'epic', 100, 'gece-limani', '{"name":{"tr":"Gece Vardiyası","en":"Night Watch","de":"Nachtwache","es":"Guardia nocturna","fr":"Veille de nuit","pt-BR":"Vigília noturna","ru":"Ночная вахта"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: sisli rıhtım, fener ışığı ve sakin dalgalar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a foggy pier, a lighthouse beam and calm waves. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: ein nebliger Kai, ein Leuchtturmstrahl und ruhige Wellen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: un muelle con niebla, la luz de un faro y olas tranquilas. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : un quai dans la brume, le faisceau d''un phare et des vagues calmes. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: um cais com neblina, o facho de um farol e ondas calmas. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: туманный причал, луч маяка и спокойные волны. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","sea","night","light"]'::jsonb, NULL),
('s2-voice_tile-bakir-kervan', 'Oasis Dusk', 'The tile everyone sees in voice channels and calls: dunes at sunset and a caravan on the move. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 600, NULL, NULL, 'vt-bakir-kervan', 'epic', 101, 'bakir-kervan', '{"name":{"tr":"Vaha Akşamı","en":"Oasis Dusk","de":"Oasenabend","es":"Atardecer en el oasis","fr":"Soir d''oasis","pt-BR":"Entardecer no oásis","ru":"Вечер в оазисе"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: gün batımında kum tepeleri ve yola çıkan bir kervan. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: dunes at sunset and a caravan on the move. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Dünen im Sonnenuntergang und eine ziehende Karawane. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: dunas al atardecer y una caravana en marcha. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des dunes au couchant et une caravane en route. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: dunas ao pôr do sol e uma caravana a caminho. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: дюны на закате и караван в пути. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","desert","sunset","warm"]'::jsonb, NULL),
('s2-voice_tile-orkide-sisi', 'Greenhouse Glow', 'The tile everyone sees in voice channels and calls: orchids glowing in a night greenhouse and drifting pollen. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 680, NULL, NULL, 'vt-orkide-sisi', 'epic', 102, 'orkide-sisi', '{"name":{"tr":"Sera Işığı","en":"Greenhouse Glow","de":"Gewächshausschein","es":"Luz de invernadero","fr":"Lueur de serre","pt-BR":"Luz da estufa","ru":"Свет оранжереи"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: gece serasında parlayan orkideler ve süzülen polen. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: orchids glowing in a night greenhouse and drifting pollen. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: leuchtende Orchideen in einem nächtlichen Gewächshaus und schwebender Pollen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: orquídeas que brillan en un invernadero de noche y polen flotando. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des orchidées lumineuses dans une serre nocturne et du pollen en suspension. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: orquídeas brilhando numa estufa à noite e pólen flutuando. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: светящиеся орхидеи в ночной оранжерее и парящая пыльца. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","flower","glow","night"]'::jsonb, NULL),
('s2-voice_tile-kor-bahcesi', 'Ember Bed', 'The tile everyone sees in voice channels and calls: flowers with petals of flame and rising sparks. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 660, NULL, NULL, 'vt-kor-bahcesi', 'epic', 103, 'kor-bahcesi', '{"name":{"tr":"Kor Tarhı","en":"Ember Bed","de":"Glutbeet","es":"Lecho de brasas","fr":"Parterre de braises","pt-BR":"Canteiro de brasas","ru":"Клумба углей"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: alev yapraklı çiçekler ve yükselen kıvılcımlar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: flowers with petals of flame and rising sparks. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Blumen mit Flammenblättern und aufsteigende Funken. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: flores con pétalos de llama y chispas que suben. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des fleurs aux pétales de flamme et des étincelles qui montent. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: flores com pétalas de chama e faíscas subindo. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: цветы с лепестками из пламени и взлетающие искры. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","fire","flower","warm"]'::jsonb, NULL),
('s2-voice_tile-buzul-sessizligi', 'Ice Hall', 'The tile everyone sees in voice channels and calls: ice crystals that split the light and slowly falling snow. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 620, NULL, NULL, 'vt-buzul-sessizligi', 'epic', 104, 'buzul-sessizligi', '{"name":{"tr":"Buz Sarayı","en":"Ice Hall","de":"Eishalle","es":"Salón de hielo","fr":"Salle de glace","pt-BR":"Salão de gelo","ru":"Ледяной зал"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: ışığı kıran buz kristalleri ve yavaşça düşen kar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: ice crystals that split the light and slowly falling snow. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Eiskristalle, die das Licht brechen, und langsam fallender Schnee. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: cristales de hielo que parten la luz y nieve que cae despacio. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des cristaux de glace qui brisent la lumière et une neige lente. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: cristais de gelo que quebram a luz e neve caindo devagar. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: ледяные кристаллы, преломляющие свет, и медленный снег. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","ice","snow","cool"]'::jsonb, NULL),
('s2-voice_tile-neon-carsi', 'Rainy Arcade', 'The tile everyone sees in voice channels and calls: neon signs, paper lanterns and reflections on a wet street. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 700, NULL, NULL, 'vt-neon-carsi', 'epic', 105, 'neon-carsi', '{"name":{"tr":"Yağmurlu Pasaj","en":"Rainy Arcade","de":"Regenpassage","es":"Pasaje bajo la lluvia","fr":"Passage sous la pluie","pt-BR":"Galeria na chuva","ru":"Пассаж под дождём"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: neon tabelalar, kağıt fenerler ve ıslak sokakta yansımalar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: neon signs, paper lanterns and reflections on a wet street. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Neonschilder, Papierlaternen und Spiegelungen auf nasser Straße. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: letreros de neón, farolillos de papel y reflejos en la calle mojada. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des enseignes néon, des lanternes en papier et des reflets sur la rue mouillée. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: letreiros de neon, lanternas de papel e reflexos na rua molhada. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: неоновые вывески, бумажные фонари и отражения на мокрой улице. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","neon","city","rain"]'::jsonb, NULL),
('s2-voice_tile-altin-hasat', 'Wheat Field', 'The tile everyone sees in voice channels and calls: a low sun, long rays of light and golden wheat. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 610, NULL, NULL, 'vt-altin-hasat', 'epic', 106, 'altin-hasat', '{"name":{"tr":"Başak Tarlası","en":"Wheat Field","de":"Weizenfeld","es":"Campo de trigo","fr":"Champ de blé","pt-BR":"Campo de trigo","ru":"Пшеничное поле"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: alçak güneş, uzanan ışık huzmeleri ve altın başaklar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a low sun, long rays of light and golden wheat. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: tief stehende Sonne, lange Lichtstrahlen und goldener Weizen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: un sol bajo, largos rayos de luz y trigo dorado. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : un soleil bas, de longs rayons et des blés dorés. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: sol baixo, longos raios de luz e trigo dourado. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: низкое солнце, длинные лучи и золотая пшеница. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","gold","sun","field"]'::jsonb, NULL),
('s2-voice_tile-mor-sis', 'Nebula Room', 'The tile everyone sees in voice channels and calls: a violet nebula, soft dust arms and twinkling stars. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 640, NULL, NULL, 'vt-mor-sis', 'epic', 107, 'mor-sis', '{"name":{"tr":"Nebula Odası","en":"Nebula Room","de":"Nebula-Raum","es":"Sala nebulosa","fr":"Salle nébuleuse","pt-BR":"Sala nebulosa","ru":"Туманная комната"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: mor bulutsu, yumuşak toz kolları ve parıldayan yıldızlar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a violet nebula, soft dust arms and twinkling stars. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: ein violetter Nebel, sanfte Staubarme und funkelnde Sterne. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: una nebulosa violeta, brazos de polvo suaves y estrellas que titilan. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : une nébuleuse violette, de doux bras de poussière et des étoiles scintillantes. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: uma nebulosa violeta, braços de poeira suaves e estrelas cintilantes. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: фиолетовая туманность, мягкие рукава пыли и мерцающие звёзды. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","space","violet","stars"]'::jsonb, NULL),
('s2-voice_tile-gece-mercani', 'Reef Glow', 'The tile everyone sees in voice channels and calls: corals glowing at night, anemones and rising bubbles. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 660, NULL, NULL, 'vt-gece-mercani', 'epic', 108, 'gece-mercani', '{"name":{"tr":"Resif Işıltısı","en":"Reef Glow","de":"Riffleuchten","es":"Brillo del arrecife","fr":"Lueur du récif","pt-BR":"Brilho do recife","ru":"Сияние рифа"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: gece parlayan mercanlar, anemonlar ve yükselen kabarcıklar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: corals glowing at night, anemones and rising bubbles. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: nachts leuchtende Korallen, Anemonen und aufsteigende Blasen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: corales que brillan de noche, anémonas y burbujas que suben. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des coraux qui brillent la nuit, des anémones et des bulles qui montent. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: corais brilhando à noite, anêmonas e bolhas subindo. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: светящиеся ночью кораллы, анемоны и поднимающиеся пузырьки. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","sea","coral","glow"]'::jsonb, NULL),
('s2-voice_tile-kuzey-isigi', 'Aurora Curtain', 'The tile everyone sees in voice channels and calls: polar lights rippling over mountains and a mirror lake. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 690, NULL, NULL, 'vt-kuzey-isigi', 'epic', 109, 'kuzey-isigi', '{"name":{"tr":"Aurora Perdesi","en":"Aurora Curtain","de":"Polarlichtvorhang","es":"Cortina de aurora","fr":"Rideau d''aurore","pt-BR":"Cortina de aurora","ru":"Занавес сияния"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: dağların üstünde dalgalanan kutup ışıkları ve göl yansıması. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: polar lights rippling over mountains and a mirror lake. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Polarlichter, die über Bergen wogen, und ein spiegelnder See. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: luces polares ondeando sobre montañas y un lago espejo. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des lumières polaires qui ondulent sur les montagnes et un lac miroir. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: luzes polares ondulando sobre montanhas e um lago espelhado. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: полярное сияние над горами и зеркальное озеро. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","aurora","night","mountain"]'::jsonb, NULL),
('s2-voice_tile-zumrut-orman', 'Firefly Trail', 'The tile everyone sees in voice channels and calls: a misty pine forest, moonlight and wandering fireflies. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 620, NULL, NULL, 'vt-zumrut-orman', 'epic', 110, 'zumrut-orman', '{"name":{"tr":"Ateşböceği Yolu","en":"Firefly Trail","de":"Glühwürmchenpfad","es":"Sendero de luciérnagas","fr":"Sentier des lucioles","pt-BR":"Trilha dos vaga-lumes","ru":"Тропа светлячков"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: sisli çam ormanı, ay ışığı ve dolaşan ateşböcekleri. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a misty pine forest, moonlight and wandering fireflies. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: ein nebliger Kiefernwald, Mondlicht und umherziehende Glühwürmchen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: un pinar con niebla, luz de luna y luciérnagas errantes. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : une pinède brumeuse, la lune et des lucioles vagabondes. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: um pinheiral com neblina, luar e vaga-lumes errantes. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: туманный сосновый лес, лунный свет и блуждающие светлячки. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","forest","night","green"]'::jsonb, NULL),
('s2-voice_tile-kum-saati', 'Sand Ripple', 'The tile everyone sees in voice channels and calls: an ivory sun, rippled sand and time running through. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 600, NULL, NULL, 'vt-kum-saati', 'epic', 111, 'kum-saati', '{"name":{"tr":"Kum Dalgası","en":"Sand Ripple","de":"Sandwelle","es":"Onda de arena","fr":"Vague de sable","pt-BR":"Onda de areia","ru":"Песчаная рябь"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: fildişi güneş, kum dalgaları ve akan zaman. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: an ivory sun, rippled sand and time running through. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: eine elfenbeinfarbene Sonne, gewellter Sand und verrinnende Zeit. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: un sol de marfil, arena ondulada y el tiempo que corre. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : un soleil d''ivoire, du sable ondulé et le temps qui s''écoule. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: um sol de marfim, areia ondulada e o tempo escorrendo. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: солнце цвета слоновой кости, песчаная рябь и текущее время. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","sand","time","warm"]'::jsonb, NULL),
('s2-voice_tile-firtina-cekirdegi', 'Eye of Lightning', 'The tile everyone sees in voice channels and calls: heavy clouds, a striking bolt and slanting rain. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 680, NULL, NULL, 'vt-firtina-cekirdegi', 'epic', 112, 'firtina-cekirdegi', '{"name":{"tr":"Şimşek Gözü","en":"Eye of Lightning","de":"Blitzauge","es":"Ojo del rayo","fr":"Œil de l''éclair","pt-BR":"Olho do raio","ru":"Око молнии"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: ağır bulutlar, çakan bir şimşek ve eğik yağmur. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: heavy clouds, a striking bolt and slanting rain. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: schwere Wolken, ein einschlagender Blitz und schräger Regen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: nubes pesadas, un rayo que cae y lluvia inclinada. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des nuages lourds, un éclair qui frappe et une pluie oblique. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: nuvens pesadas, um raio caindo e chuva inclinada. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: тяжёлые тучи, удар молнии и косой дождь. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","storm","rain","electric"]'::jsonb, NULL),
('s2-voice_tile-lav-akisi', 'Magma Plate', 'The tile everyone sees in voice channels and calls: black rock plates with fire flowing between them. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 700, NULL, NULL, 'vt-lav-akisi', 'epic', 113, 'lav-akisi', '{"name":{"tr":"Magma Plakası","en":"Magma Plate","de":"Magmaplatte","es":"Placa de magma","fr":"Plaque de magma","pt-BR":"Placa de magma","ru":"Магмовая плита"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: kara kaya plakaları ve aralarında akan ateş. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: black rock plates with fire flowing between them. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: schwarze Felsplatten, zwischen denen Feuer fließt. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: placas de roca negra con fuego fluyendo entre ellas. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des plaques de roche noire et du feu qui coule entre elles. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: placas de rocha negra com fogo correndo entre elas. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: чёрные каменные плиты и огонь, текущий между ними. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","lava","fire","dark"]'::jsonb, NULL),
('s2-voice_tile-inci-kiyisi', 'Nacre Cove', 'The tile everyone sees in voice channels and calls: pearls, an open seashell and a foamy shore. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 620, NULL, NULL, 'vt-inci-kiyisi', 'epic', 114, 'inci-kiyisi', '{"name":{"tr":"Sedef Koy","en":"Nacre Cove","de":"Perlmuttbucht","es":"Cala de nácar","fr":"Crique de nacre","pt-BR":"Enseada de madrepérola","ru":"Перламутровая бухта"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: inciler, açık bir deniz kabuğu ve köpüklü kıyı. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: pearls, an open seashell and a foamy shore. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Perlen, eine offene Muschel und ein schäumendes Ufer. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: perlas, una concha abierta y una orilla con espuma. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des perles, un coquillage ouvert et un rivage d''écume. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: pérolas, uma concha aberta e uma praia de espuma. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: жемчуг, раскрытая раковина и пенный берег. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","sea","pearl","soft"]'::jsonb, NULL),
('s2-voice_tile-yildiz-tozu', 'Galaxy Arm', 'The tile everyone sees in voice channels and calls: a galaxy arm across the sky and bright stardust. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 700, NULL, NULL, 'vt-yildiz-tozu', 'epic', 115, 'yildiz-tozu', '{"name":{"tr":"Galaksi Kolu","en":"Galaxy Arm","de":"Galaxienarm","es":"Brazo galáctico","fr":"Bras galactique","pt-BR":"Braço galáctico","ru":"Рукав галактики"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: çapraz uzanan bir galaksi kolu ve parlak yıldız tozu. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a galaxy arm across the sky and bright stardust. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: ein Galaxienarm quer über den Himmel und heller Sternenstaub. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: un brazo galáctico cruzando el cielo y polvo de estrellas brillante. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : un bras galactique qui traverse le ciel et une poussière d''étoiles. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: um braço galáctico cruzando o céu e poeira estelar brilhante. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: рукав галактики через всё небо и яркая звёздная пыль. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","set","space","stars","gold"]'::jsonb, NULL),
('s2-voice_tile-ebru-aksami', 'Marbled Evening', 'The tile everyone sees in voice channels and calls: marbled drops blooming on water and combed colours. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 780, NULL, NULL, 'vt-ebru-aksami', 'epic', 316, NULL, '{"name":{"tr":"Ebru Akşamı","en":"Marbled Evening","de":"Marmorabend","es":"Tarde jaspeada","fr":"Soir marbré","pt-BR":"Entardecer marmorizado","ru":"Мраморный вечер"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: su üstünde açılan ebru damlaları ve taranmış renkler. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: marbled drops blooming on water and combed colours. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: auf Wasser erblühende Marmortropfen und gekämmte Farben. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: gotas jaspeadas que florecen sobre el agua y colores peinados. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des gouttes marbrées qui s''ouvrent sur l''eau et des couleurs peignées. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: gotas marmorizadas abrindo na água e cores penteadas. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: мраморные капли, раскрывающиеся на воде, и прочёсанные цвета. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","art","pattern","warm"]'::jsonb, NULL),
('s2-voice_tile-iznik-cinisi', 'Iznik Tile', 'The tile everyone sees in voice channels and calls: cobalt star patterns and tulip motifs. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 1280, NULL, NULL, 'vt-iznik-cinisi', 'legendary', 317, NULL, '{"name":{"tr":"İznik Çinisi","en":"Iznik Tile","de":"Iznik-Fliese","es":"Azulejo de Iznik","fr":"Carreau d''Iznik","pt-BR":"Azulejo de Iznik","ru":"Изникская плитка"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: kobalt mavisi yıldız desenleri ve lale motifleri. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: cobalt star patterns and tulip motifs. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: kobaltblaue Sternmuster und Tulpenmotive. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: estrellas en azul cobalto y motivos de tulipán. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des motifs d''étoiles bleu cobalt et des tulipes. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: padrões de estrelas azul-cobalto e motivos de tulipa. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: кобальтовые звёздные узоры и мотивы тюльпанов. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","art","pattern","blue"]'::jsonb, NULL),
('s2-voice_tile-kilim', 'Kilim', 'The tile everyone sees in voice channels and calls: woven bands, diamonds and warm earth colours. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 420, NULL, NULL, 'vt-kilim', 'rare', 318, NULL, '{"name":{"tr":"Kilim","en":"Kilim","de":"Kelim","es":"Kilim","fr":"Kilim","pt-BR":"Kilim","ru":"Килим"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: dokuma şeritler, eşkenar dörtgenler ve sıcak toprak renkleri. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: woven bands, diamonds and warm earth colours. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: gewebte Streifen, Rauten und warme Erdtöne. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: franjas tejidas, rombos y cálidos colores tierra. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des bandes tissées, des losanges et des tons de terre chauds. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: faixas tecidas, losangos e tons quentes de terra. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: тканые полосы, ромбы и тёплые земляные цвета. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","art","pattern","warm"]'::jsonb, NULL),
('s2-voice_tile-balon-vadisi', 'Balloon Valley', 'The tile everyone sees in voice channels and calls: fairy chimneys at dawn and drifting hot air balloons. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 1350, NULL, NULL, 'vt-balon-vadisi', 'legendary', 319, NULL, '{"name":{"tr":"Balon Vadisi","en":"Balloon Valley","de":"Ballontal","es":"Valle de globos","fr":"Vallée des montgolfières","pt-BR":"Vale dos balões","ru":"Долина шаров"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: şafakta peri bacaları ve süzülen sıcak hava balonları. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: fairy chimneys at dawn and drifting hot air balloons. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Feenkamine im Morgengrauen und treibende Heißluftballons. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: chimeneas de hadas al amanecer y globos aerostáticos flotando. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des cheminées de fée à l''aube et des montgolfières qui dérivent. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: chaminés de fada ao amanhecer e balões de ar quente flutuando. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: скальные столбы на рассвете и парящие воздушные шары. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","landscape","dawn","warm"]'::jsonb, NULL),
('s2-voice_tile-bogaz-gecesi', 'Strait at Night', 'The tile everyone sees in voice channels and calls: a lit suspension bridge, a city on the hills and reflections on the water. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 820, NULL, NULL, 'vt-bogaz-gecesi', 'epic', 320, NULL, '{"name":{"tr":"Boğaz Gecesi","en":"Strait at Night","de":"Meerenge bei Nacht","es":"Estrecho de noche","fr":"Détroit la nuit","pt-BR":"Estreito à noite","ru":"Ночной пролив"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: ışıklı bir asma köprü, tepelerde şehir ve suda yansımalar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a lit suspension bridge, a city on the hills and reflections on the water. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: eine beleuchtete Hängebrücke, eine Stadt auf den Hügeln und Spiegelungen im Wasser. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: un puente colgante iluminado, una ciudad en las colinas y reflejos en el agua. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : un pont suspendu illuminé, une ville sur les collines et des reflets sur l''eau. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: uma ponte pênsil iluminada, uma cidade nas colinas e reflexos na água. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: освещённый висячий мост, город на холмах и отражения в воде. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","city","night","sea"]'::jsonb, NULL),
('s2-voice_tile-murekkep-daglari', 'Ink Mountains', 'The tile everyone sees in voice channels and calls: layered misty mountains, a red sun and still water. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 480, NULL, NULL, 'vt-murekkep-daglari', 'rare', 321, NULL, '{"name":{"tr":"Mürekkep Dağları","en":"Ink Mountains","de":"Tuscheberge","es":"Montañas de tinta","fr":"Montagnes d''encre","pt-BR":"Montanhas de nanquim","ru":"Горы тушью"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: katman katman sisli dağlar, kızıl güneş ve durgun su. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: layered misty mountains, a red sun and still water. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: geschichtete Nebelberge, eine rote Sonne und stilles Wasser. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: montañas con niebla en capas, un sol rojo y agua quieta. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des montagnes brumeuses en couches, un soleil rouge et une eau calme. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: montanhas em camadas de neblina, um sol vermelho e água parada. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: слои туманных гор, красное солнце и тихая вода. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","landscape","calm","mono"]'::jsonb, NULL),
('s2-voice_tile-holo-folyo', 'Holo Foil', 'The tile everyone sees in voice channels and calls: an iridescent surface that shifts colour with the light. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 860, NULL, NULL, 'vt-holo-folyo', 'epic', 322, NULL, '{"name":{"tr":"Holo Folyo","en":"Holo Foil","de":"Holofolie","es":"Lámina holográfica","fr":"Feuille holo","pt-BR":"Folha holográfica","ru":"Голофольга"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: ışığa göre renk değiştiren yanardöner bir yüzey. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: an iridescent surface that shifts colour with the light. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: eine schillernde Oberfläche, die mit dem Licht die Farbe wechselt. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: una superficie iridiscente que cambia de color con la luz. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : une surface irisée qui change de couleur avec la lumière. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: uma superfície iridescente que muda de cor com a luz. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: переливчатая поверхность, меняющая цвет на свету. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","iridescent","shine","colourful"]'::jsonb, NULL),
('s2-voice_tile-bulutlarin-ustu', 'Above the Clouds', 'The tile everyone sees in voice channels and calls: the sun rising over a sea of clouds. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 380, NULL, NULL, 'vt-bulutlarin-ustu', 'rare', 323, NULL, '{"name":{"tr":"Bulutların Üstü","en":"Above the Clouds","de":"Über den Wolken","es":"Sobre las nubes","fr":"Au-dessus des nuages","pt-BR":"Acima das nuvens","ru":"Над облаками"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: bulut denizinin üstünde doğan güneş. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: the sun rising over a sea of clouds. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: die Sonne, die über einem Wolkenmeer aufgeht. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: el sol saliendo sobre un mar de nubes. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : le soleil qui se lève sur une mer de nuages. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: o sol nascendo sobre um mar de nuvens. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: солнце, встающее над морем облаков. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","sky","dawn","soft"]'::jsonb, NULL),
('s2-voice_tile-yagmurlu-cam', 'Rainy Glass', 'The tile everyone sees in voice channels and calls: raindrops on glass and blurred city lights behind it. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 720, NULL, NULL, 'vt-yagmurlu-cam', 'epic', 324, NULL, '{"name":{"tr":"Yağmurlu Cam","en":"Rainy Glass","de":"Regenglas","es":"Cristal con lluvia","fr":"Vitre sous la pluie","pt-BR":"Vidro com chuva","ru":"Дождливое стекло"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: camda yağmur damlaları ve ardında bulanık şehir ışıkları. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: raindrops on glass and blurred city lights behind it. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Regentropfen auf Glas und verschwommene Stadtlichter dahinter. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: gotas de lluvia en el cristal y luces de ciudad borrosas detrás. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des gouttes sur la vitre et des lumières de ville floues derrière. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: gotas de chuva no vidro e luzes da cidade desfocadas atrás. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: капли дождя на стекле и размытые огни города за ним. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","rain","city","bokeh"]'::jsonb, NULL),
('s2-voice_tile-gece-plagi', 'Midnight Record', 'The tile everyone sees in voice channels and calls: a spinning record, a sheen of light and a tone arm. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 460, NULL, NULL, 'vt-gece-plagi', 'rare', 325, NULL, '{"name":{"tr":"Gece Plağı","en":"Midnight Record","de":"Mitternachtsplatte","es":"Disco de medianoche","fr":"Vinyle de minuit","pt-BR":"Disco da meia-noite","ru":"Полночная пластинка"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: dönen bir plak, ışık yansıması ve pikap kolu. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a spinning record, a sheen of light and a tone arm. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: eine drehende Platte, ein Lichtschimmer und ein Tonarm. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: un disco que gira, un brillo de luz y un brazo de tocadiscos. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : un disque qui tourne, un reflet de lumière et un bras de platine. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: um disco girando, um brilho de luz e um braço de toca-discos. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: вращающаяся пластинка, блик света и тонарм. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","music","retro","warm"]'::jsonb, NULL);
INSERT INTO _shop2_seed (sku, name, description, category, asset_url, preview_url, price_descoin, theme_key, badge_icon, effect_key, rarity, sort_order, set_key, i18n, tags, meta) VALUES
('s2-voice_tile-ekolayzer', 'Equalizer', 'The tile everyone sees in voice channels and calls: bright frequency bars rising with the beat. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 240, NULL, NULL, 'vt-ekolayzer', 'common', 326, NULL, '{"name":{"tr":"Ekolayzer","en":"Equalizer","de":"Equalizer","es":"Ecualizador","fr":"Égaliseur","pt-BR":"Equalizador","ru":"Эквалайзер"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: ritimle yükselen parlak frekans çubukları. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: bright frequency bars rising with the beat. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: helle Frequenzbalken, die im Takt steigen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: barras de frecuencia brillantes que suben con el ritmo. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des barres de fréquence lumineuses qui montent avec le rythme. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: barras de frequência brilhantes subindo com a batida. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: яркие частотные столбики, растущие в такт. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","music","neon","blue"]'::jsonb, NULL),
('s2-voice_tile-prizma', 'Prism', 'The tile everyone sees in voice channels and calls: light passing through a glass prism and splitting into a rainbow. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 640, NULL, NULL, 'vt-prizma', 'epic', 327, NULL, '{"name":{"tr":"Prizma","en":"Prism","de":"Prisma","es":"Prisma","fr":"Prisme","pt-BR":"Prisma","ru":"Призма"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: bir cam prizmadan geçip gökkuşağına ayrılan ışık. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: light passing through a glass prism and splitting into a rainbow. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Licht, das durch ein Glasprisma fällt und sich in einen Regenbogen teilt. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: luz que atraviesa un prisma de cristal y se abre en arcoíris. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : la lumière qui traverse un prisme et se sépare en arc-en-ciel. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: luz atravessando um prisma de vidro e se abrindo em arco-íris. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: свет, проходящий через стеклянную призму и распадающийся радугой. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","light","rainbow","dark"]'::jsonb, NULL),
('s2-voice_tile-lacivert-duman', 'Indigo Smoke', 'The tile everyone sees in voice channels and calls: ribbons of smoke curling slowly upward. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 200, NULL, NULL, 'vt-lacivert-duman', 'common', 328, NULL, '{"name":{"tr":"Lacivert Duman","en":"Indigo Smoke","de":"Indigorauch","es":"Humo índigo","fr":"Fumée indigo","pt-BR":"Fumaça índigo","ru":"Индиговый дым"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: yavaşça kıvrılarak yükselen duman şeritleri. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: ribbons of smoke curling slowly upward. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Rauchbänder, die sich langsam nach oben kräuseln. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: cintas de humo que suben despacio en espiral. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des rubans de fumée qui montent lentement en volutes. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: fitas de fumaça subindo devagar em espiral. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: ленты дыма, медленно завивающиеся вверх. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","smoke","blue","calm"]'::jsonb, NULL),
('s2-voice_tile-okyanus-derinligi', 'Ocean Deep', 'The tile everyone sees in voice channels and calls: light filtering from the surface, jellyfish and bubbles. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 1180, NULL, NULL, 'vt-okyanus-derinligi', 'legendary', 329, NULL, '{"name":{"tr":"Okyanus Derinliği","en":"Ocean Deep","de":"Meerestiefe","es":"Profundidad oceánica","fr":"Abysses","pt-BR":"Profundeza do oceano","ru":"Глубина океана"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: yüzeyden süzülen ışık, denizanaları ve kabarcıklar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: light filtering from the surface, jellyfish and bubbles. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: von der Oberfläche einfallendes Licht, Quallen und Blasen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: luz que baja desde la superficie, medusas y burbujas. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : la lumière qui descend de la surface, des méduses et des bulles. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: luz descendo da superfície, águas-vivas e bolhas. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: свет с поверхности, медузы и пузырьки. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","sea","deep","glow"]'::jsonb, NULL),
('s2-voice_tile-ay-tutulmasi', 'Eclipse', 'The tile everyone sees in voice channels and calls: a blazing corona behind a black disc. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 1100, NULL, NULL, 'vt-ay-tutulmasi', 'legendary', 330, NULL, '{"name":{"tr":"Ay Tutulması","en":"Eclipse","de":"Finsternis","es":"Eclipse","fr":"Éclipse","pt-BR":"Eclipse","ru":"Затмение"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: kara bir diskin ardında parlayan güneş tacı. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a blazing corona behind a black disc. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: eine gleißende Korona hinter einer schwarzen Scheibe. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: una corona ardiente detrás de un disco negro. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : une couronne éclatante derrière un disque noir. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: uma coroa ardente atrás de um disco negro. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: пылающая корона за чёрным диском. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","space","dark","gold"]'::jsonb, NULL),
('s2-voice_tile-lale-bahcesi', 'Tulip Garden', 'The tile everyone sees in voice channels and calls: red and pink tulips opening at dusk. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 400, NULL, NULL, 'vt-lale-bahcesi', 'rare', 331, NULL, '{"name":{"tr":"Lale Bahçesi","en":"Tulip Garden","de":"Tulpengarten","es":"Jardín de tulipanes","fr":"Jardin de tulipes","pt-BR":"Jardim de tulipas","ru":"Сад тюльпанов"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: alacakaranlıkta açan kırmızı ve pembe laleler. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: red and pink tulips opening at dusk. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: rote und rosa Tulpen, die sich in der Dämmerung öffnen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: tulipanes rojos y rosas abriéndose al anochecer. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des tulipes rouges et roses qui s''ouvrent au crépuscule. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: tulipas vermelhas e rosas abrindo ao entardecer. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: красные и розовые тюльпаны, раскрывающиеся в сумерках. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","flower","dusk","red"]'::jsonb, NULL),
('s2-voice_tile-kristal-petek', 'Crystal Comb', 'The tile everyone sees in voice channels and calls: glass hexagon cells, some of them lit. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 260, NULL, NULL, 'vt-kristal-petek', 'common', 332, NULL, '{"name":{"tr":"Kristal Petek","en":"Crystal Comb","de":"Kristallwabe","es":"Panal de cristal","fr":"Alvéoles de cristal","pt-BR":"Favo de cristal","ru":"Кристальные соты"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: yer yer ışıyan cam altıgen hücreler. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: glass hexagon cells, some of them lit. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: gläserne Sechseckzellen, von denen einige leuchten. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: celdas hexagonales de cristal, algunas encendidas. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des cellules hexagonales de verre, dont certaines brillent. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: células hexagonais de vidro, algumas acesas. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: стеклянные шестигранные ячейки, часть из них светится. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","pattern","glass","cool"]'::jsonb, NULL),
('s2-voice_tile-kagit-katlar', 'Paper Layers', 'The tile everyone sees in voice channels and calls: hills cut from shaded paper and a big sun. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 220, NULL, NULL, 'vt-kagit-katlar', 'common', 333, NULL, '{"name":{"tr":"Kağıt Katlar","en":"Paper Layers","de":"Papierschichten","es":"Capas de papel","fr":"Couches de papier","pt-BR":"Camadas de papel","ru":"Бумажные слои"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: gölgeli kağıttan kesilmiş tepeler ve büyük bir güneş. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: hills cut from shaded paper and a big sun. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: aus schattiertem Papier geschnittene Hügel und eine große Sonne. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: colinas recortadas en papel con sombras y un gran sol. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des collines découpées dans du papier ombré et un grand soleil. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: colinas recortadas em papel com sombras e um grande sol. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: холмы, вырезанные из бумаги с тенями, и большое солнце. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","landscape","paper","calm"]'::jsonb, NULL),
('s2-voice_tile-mum-isigi', 'Candlelight', 'The tile everyone sees in voice channels and calls: warm flames and soft spots of light in the air. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 280, NULL, NULL, 'vt-mum-isigi', 'common', 334, NULL, '{"name":{"tr":"Mum Işığı","en":"Candlelight","de":"Kerzenschein","es":"Luz de velas","fr":"Lueur de bougies","pt-BR":"Luz de velas","ru":"Свет свечей"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: sıcak alevler ve havada süzülen ışık lekeleri. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: warm flames and soft spots of light in the air. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: warme Flammen und weiche Lichtpunkte in der Luft. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: llamas cálidas y suaves destellos de luz en el aire. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des flammes chaudes et de douces taches de lumière dans l''air. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: chamas quentes e pontos de luz suaves no ar. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: тёплое пламя и мягкие пятна света в воздухе. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","warm","light","cozy"]'::jsonb, NULL),
('s2-voice_tile-pastel-aksam', 'Pastel Evening', 'The tile everyone sees in voice channels and calls: layered hills in lilac and peach. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 180, NULL, NULL, 'vt-pastel-aksam', 'common', 335, NULL, '{"name":{"tr":"Pastel Akşam","en":"Pastel Evening","de":"Pastellabend","es":"Tarde pastel","fr":"Soir pastel","pt-BR":"Entardecer pastel","ru":"Пастельный вечер"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: lila ve şeftali tonlarında katman katman dağlar. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: layered hills in lilac and peach. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: geschichtete Hügel in Flieder und Pfirsich. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: colinas en capas en lila y melocotón. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des collines en couches lilas et pêche. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: colinas em camadas lilás e pêssego. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: слоистые холмы в сиреневых и персиковых тонах. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","landscape","pastel","soft"]'::jsonb, NULL),
('s2-voice_tile-gece-sehri', 'Night City', 'The tile everyone sees in voice channels and calls: towers with lit windows and a full moon. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 440, NULL, NULL, 'vt-gece-sehri', 'rare', 336, NULL, '{"name":{"tr":"Gece Şehri","en":"Night City","de":"Nachtstadt","es":"Ciudad nocturna","fr":"Ville de nuit","pt-BR":"Cidade noturna","ru":"Ночной город"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: pencereleri yanan gökdelenler ve dolunay. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: towers with lit windows and a full moon. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: Türme mit beleuchteten Fenstern und ein Vollmond. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: torres con ventanas encendidas y luna llena. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des tours aux fenêtres allumées et une pleine lune. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: torres com janelas acesas e lua cheia. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: башни с горящими окнами и полная луна. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","city","night","lights"]'::jsonb, NULL),
('s2-voice_tile-bakir-devre', 'Copper Circuit', 'The tile everyone sees in voice channels and calls: glowing copper traces, solder pads and chips. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 500, NULL, NULL, 'vt-bakir-devre', 'rare', 337, NULL, '{"name":{"tr":"Bakır Devre","en":"Copper Circuit","de":"Kupferschaltung","es":"Circuito de cobre","fr":"Circuit de cuivre","pt-BR":"Circuito de cobre","ru":"Медная схема"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: parlayan bakır yollar, lehim noktaları ve çipler. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: glowing copper traces, solder pads and chips. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: leuchtende Kupferbahnen, Lötpunkte und Chips. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: pistas de cobre brillantes, puntos de soldadura y chips. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des pistes de cuivre lumineuses, des pastilles de soudure et des puces. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: trilhas de cobre brilhantes, pontos de solda e chips. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: светящиеся медные дорожки, контактные площадки и чипы. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","tech","copper","glow"]'::jsonb, NULL),
('s2-voice_tile-yorunge', 'Orbit', 'The tile everyone sees in voice channels and calls: a ringed planet, moons and dotted orbits. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 520, NULL, NULL, 'vt-yorunge', 'rare', 338, NULL, '{"name":{"tr":"Yörünge","en":"Orbit","de":"Umlaufbahn","es":"Órbita","fr":"Orbite","pt-BR":"Órbita","ru":"Орбита"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: halkalı bir gezegen, uydular ve noktalı yörüngeler. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: a ringed planet, moons and dotted orbits. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: ein Ringplanet, Monde und gepunktete Bahnen. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: un planeta con anillos, lunas y órbitas punteadas. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : une planète à anneaux, des lunes et des orbites en pointillé. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: um planeta com anéis, luas e órbitas pontilhadas. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: планета с кольцами, луны и пунктирные орбиты. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","space","planet","violet"]'::jsonb, NULL),
('s2-voice_tile-vitray', 'Stained Glass', 'The tile everyone sees in voice channels and calls: coloured glass pieces held by lead lines. Its edge glows in the theme colour while you talk.', 'voice_tile', 'data:,', NULL, 680, NULL, NULL, 'vt-vitray', 'epic', 339, NULL, '{"name":{"tr":"Vitray","en":"Stained Glass","de":"Buntglas","es":"Vitral","fr":"Vitrail","pt-BR":"Vitral","ru":"Витраж"},"description":{"tr":"Ses kanalında ve aramalarda herkesin gördüğü kutucuk: kurşun çizgilerle ayrılmış renkli cam parçaları. Konuşurken kenarı temanın renginde parlar.","en":"The tile everyone sees in voice channels and calls: coloured glass pieces held by lead lines. Its edge glows in the theme colour while you talk.","de":"Die Kachel, die alle in Sprachkanälen und Anrufen sehen: farbige Glasstücke zwischen Bleiruten. Beim Sprechen leuchtet der Rand in der Themenfarbe.","es":"El recuadro que todos ven en canales de voz y llamadas: piezas de cristal de colores unidas por plomo. Su borde brilla con el color del tema cuando hablas.","fr":"La tuile que tout le monde voit dans les salons vocaux et les appels : des morceaux de verre coloré sertis de plomb. Son contour s''illumine aux couleurs du thème quand tu parles.","pt-BR":"O bloco que todos veem nos canais de voz e chamadas: pedaços de vidro colorido unidos por chumbo. A borda brilha na cor do tema enquanto você fala.","ru":"Плитка, которую все видят в голосовых каналах и звонках: цветные стёкла в свинцовых переплётах. Пока вы говорите, её край светится цветом темы."}}'::jsonb, '["voice","art","glass","colourful"]'::jsonb, NULL),
('s2-join_sound-gece-limani', 'Harbor Bell', 'A short sound everyone hears when you join a voice channel: a deep harbor bell and a wave reaching the shore.', 'join_sound', 'data:,', NULL, 300, NULL, NULL, 'js-gece-limani', 'rare', 100, 'gece-limani', '{"name":{"tr":"Liman Çanı","en":"Harbor Bell","de":"Hafenglocke","es":"Campana del puerto","fr":"Cloche du port","pt-BR":"Sino do porto","ru":"Портовый колокол"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: derin bir liman çanı ve kıyıya vuran dalga.","en":"A short sound everyone hears when you join a voice channel: a deep harbor bell and a wave reaching the shore.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: eine tiefe Hafenglocke und eine Welle am Ufer.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: una campana grave de puerto y una ola que llega a la orilla.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : une cloche de port grave et une vague qui touche le rivage.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um sino grave de porto e uma onda chegando à praia.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: низкий портовый колокол и волна, набегающая на берег."}}'::jsonb, '["sound","set","length:1.45"]'::jsonb, '{"recipe":{"v":1,"dur":1.45,"gain":0.85,"echo":{"time":0.22,"fb":0.28,"mix":0.22},"voices":[{"type":"fm","f":"A3","t":0,"d":1.4,"g":0.62,"ratio":3.5,"idx":3.2,"idxD":0.9799999999999999,"env":{"a":0.002,"d":1.26}},{"type":"fm","f":"E4","t":0.02,"d":1.2,"g":0.3,"ratio":2.76,"idx":1.6,"idxD":0.84,"env":{"a":0.002,"d":1.08},"pan":0.2},{"type":"noise","col":"brown","t":0,"d":1.4,"g":0.35,"env":{"a":0.45,"d":0.6,"s":0.6,"r":0.5},"filt":{"type":"lowpass","f":380,"f2":900,"q":0.7}},{"type":"osc","w":"sine","f":"E6","t":0.5,"d":0.5,"g":0.06,"env":{"a":0.003,"d":0.45},"pan":-0.4}]}}'::jsonb),
('s2-join_sound-bakir-kervan', 'Caravan Bells', 'A short sound everyone hears when you join a voice channel: a wooden knock followed by ringing little brass bells.', 'join_sound', 'data:,', NULL, 280, NULL, NULL, 'js-bakir-kervan', 'rare', 101, 'bakir-kervan', '{"name":{"tr":"Kervan Zili","en":"Caravan Bells","de":"Karawanenglocken","es":"Cascabeles de caravana","fr":"Clochettes de caravane","pt-BR":"Sinos da caravana","ru":"Караванные бубенцы"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: ahşap bir tık ve ardından çınlayan küçük pirinç ziller.","en":"A short sound everyone hears when you join a voice channel: a wooden knock followed by ringing little brass bells.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein Holzklopfen, dann klingende kleine Messingglocken.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un golpe de madera y luego campanitas de latón.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un coup de bois puis de petites clochettes de laiton.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: uma batida de madeira e depois sininhos de latão.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: деревянный стук и звон маленьких латунных бубенцов."}}'::jsonb, '["sound","set","length:1.1"]'::jsonb, '{"recipe":{"v":1,"dur":1.1,"gain":0.85,"echo":{"time":0.14,"fb":0.22,"mix":0.2},"voices":[{"type":"osc","w":"triangle","f":"G3","f2":"D3","gl":0.08,"t":0,"d":0.14,"g":0.5,"env":{"a":0.002,"d":0.12}},{"type":"fm","f":"C6","t":0.02,"d":0.4,"g":0.32,"ratio":2.31,"idx":1.4,"idxD":0.27999999999999997,"env":{"a":0.002,"d":0.36000000000000004},"pan":-0.3},{"type":"fm","f":"E6","t":0.14,"d":0.38,"g":0.28,"ratio":2.31,"idx":1.4,"idxD":0.26599999999999996,"env":{"a":0.002,"d":0.342},"pan":0.3},{"type":"fm","f":"D6","t":0.27,"d":0.38,"g":0.26,"ratio":2.31,"idx":1.4,"idxD":0.26599999999999996,"env":{"a":0.002,"d":0.342},"pan":-0.1},{"type":"fm","f":"G6","t":0.43,"d":0.62,"g":0.3,"ratio":2.31,"idx":1.4,"idxD":0.434,"env":{"a":0.002,"d":0.558},"pan":0.15},{"type":"noise","col":"white","t":0.43,"d":0.08,"g":0.06,"env":{"a":0.002,"d":0.06},"filt":{"type":"highpass","f":6000}}]}}'::jsonb),
('s2-join_sound-orkide-sisi', 'Dewdrop', 'A short sound everyone hears when you join a voice channel: three bright drops sliding off the petals.', 'join_sound', 'data:,', NULL, 320, NULL, NULL, 'js-orkide-sisi', 'rare', 102, 'orkide-sisi', '{"name":{"tr":"Çiy Damlası","en":"Dewdrop","de":"Tautropfen","es":"Gota de rocío","fr":"Goutte de rosée","pt-BR":"Gota de orvalho","ru":"Капля росы"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: yapraklardan süzülen üç parlak damla.","en":"A short sound everyone hears when you join a voice channel: three bright drops sliding off the petals.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: drei helle Tropfen, die von den Blüten gleiten.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: tres gotas brillantes que resbalan de los pétalos.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : trois gouttes claires qui glissent des pétales.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: três gotas brilhantes escorrendo das pétalas.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: три звонкие капли, скатывающиеся с лепестков."}}'::jsonb, '["sound","set","length:1.2"]'::jsonb, '{"recipe":{"v":1,"dur":1.2,"gain":0.8,"echo":{"time":0.19,"fb":0.35,"mix":0.3},"voices":[{"type":"osc","w":"sine","f":"A5","t":0,"d":0.2,"g":0.55,"env":{"a":0.002,"d":0.18},"f2":"E6","gl":0.06},{"type":"osc","w":"sine","f":"C6","t":0.22,"d":0.2,"g":0.45,"env":{"a":0.002,"d":0.18},"f2":"G6","gl":0.06,"pan":0.3},{"type":"osc","w":"sine","f":"E6","t":0.4,"d":0.3,"g":0.4,"env":{"a":0.002,"d":0.26},"f2":"B6","gl":0.07,"pan":-0.3},{"type":"noise","col":"pink","t":0.05,"d":0.9,"g":0.08,"env":{"a":0.25,"d":0.6,"s":0.4,"r":0.3},"filt":{"type":"highpass","f":6000}}]}}'::jsonb),
('s2-join_sound-kor-bahcesi', 'Ember Crackle', 'A short sound everyone hears when you join a voice channel: a warm hum and crackling sparks.', 'join_sound', 'data:,', NULL, 310, NULL, NULL, 'js-kor-bahcesi', 'rare', 103, 'kor-bahcesi', '{"name":{"tr":"Kor Çıtırtısı","en":"Ember Crackle","de":"Glutknistern","es":"Crepitar de brasas","fr":"Crépitement de braises","pt-BR":"Estalo de brasas","ru":"Треск углей"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: sıcak bir uğultu ve çıtırdayan kıvılcımlar.","en":"A short sound everyone hears when you join a voice channel: a warm hum and crackling sparks.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein warmes Summen und knisternde Funken.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un zumbido cálido y chispas que crepitan.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un bourdonnement chaud et des étincelles qui crépitent.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um zumbido quente e faíscas estalando.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: тёплый гул и потрескивающие искры."}}'::jsonb, '["sound","set","length:1.1"]'::jsonb, '{"recipe":{"v":1,"dur":1.1,"gain":0.85,"voices":[{"type":"osc","w":"triangle","f":"D3","t":0,"d":1.05,"g":0.4,"env":{"a":0.08,"d":0.9},"filt":{"type":"lowpass","f":900}},{"type":"fm","f":"D4","ratio":1,"idx":0.8,"idxD":0.6,"t":0.03,"d":0.9,"g":0.22,"env":{"a":0.04,"d":0.8}},{"type":"noise","col":"white","t":0,"d":0.04,"g":0.5,"pan":-0.35,"env":{"a":0.001,"d":0.03},"filt":{"type":"bandpass","f":2400,"q":2}},{"type":"noise","col":"white","t":0.07,"d":0.04,"g":0.35,"pan":0.35,"env":{"a":0.001,"d":0.03},"filt":{"type":"bandpass","f":2700,"q":2}},{"type":"noise","col":"white","t":0.16,"d":0.04,"g":0.45,"pan":-0.35,"env":{"a":0.001,"d":0.03},"filt":{"type":"bandpass","f":3000,"q":2}},{"type":"noise","col":"white","t":0.31,"d":0.04,"g":0.3,"pan":0.35,"env":{"a":0.001,"d":0.03},"filt":{"type":"bandpass","f":3300,"q":2}},{"type":"noise","col":"white","t":0.45,"d":0.04,"g":0.38,"pan":-0.35,"env":{"a":0.001,"d":0.03},"filt":{"type":"bandpass","f":3600,"q":2}},{"type":"noise","col":"white","t":0.63,"d":0.04,"g":0.25,"pan":0.35,"env":{"a":0.001,"d":0.03},"filt":{"type":"bandpass","f":3900,"q":2}},{"type":"noise","col":"white","t":0.8,"d":0.04,"g":0.18,"pan":-0.35,"env":{"a":0.001,"d":0.03},"filt":{"type":"bandpass","f":4200,"q":2}}]}}'::jsonb),
('s2-join_sound-buzul-sessizligi', 'Ice Crystal', 'A short sound everyone hears when you join a voice channel: clear glassy chimes with a long echo.', 'join_sound', 'data:,', NULL, 300, NULL, NULL, 'js-buzul-sessizligi', 'rare', 104, 'buzul-sessizligi', '{"name":{"tr":"Buz Kristali","en":"Ice Crystal","de":"Eiskristall","es":"Cristal de hielo","fr":"Cristal de glace","pt-BR":"Cristal de gelo","ru":"Ледяной кристалл"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: yankılanan berrak cam tınıları.","en":"A short sound everyone hears when you join a voice channel: clear glassy chimes with a long echo.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: klare, gläserne Töne mit langem Nachhall.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: tintineos cristalinos con un eco largo.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : des tintements cristallins avec un long écho.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: tilintares cristalinos com um eco longo.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: чистые стеклянные звоны с долгим эхом."}}'::jsonb, '["sound","set","length:1.4"]'::jsonb, '{"recipe":{"v":1,"dur":1.4,"gain":0.8,"echo":{"time":0.24,"fb":0.4,"mix":0.35},"voices":[{"type":"fm","f":"E6","t":0,"d":0.9,"g":0.38,"ratio":5.1,"idx":1.2,"idxD":0.63,"env":{"a":0.002,"d":0.81},"pan":-0.2},{"type":"fm","f":"B6","t":0.11,"d":0.8,"g":0.28,"ratio":5.1,"idx":1.1,"idxD":0.5599999999999999,"env":{"a":0.002,"d":0.7200000000000001},"pan":0.25},{"type":"osc","w":"sine","f":"E7","t":0.22,"d":0.6,"g":0.16,"env":{"a":0.003,"d":0.54}},{"type":"noise","col":"white","t":0,"d":0.3,"g":0.1,"env":{"a":0.002,"d":0.25},"filt":{"type":"highpass","f":8000}}]}}'::jsonb),
('s2-join_sound-neon-carsi', 'Neon Sign', 'A short sound everyone hears when you join a voice channel: a climbing synth arpeggio and an electric hum.', 'join_sound', 'data:,', NULL, 330, NULL, NULL, 'js-neon-carsi', 'rare', 105, 'neon-carsi', '{"name":{"tr":"Neon Tabela","en":"Neon Sign","de":"Neonschild","es":"Letrero de neón","fr":"Enseigne néon","pt-BR":"Letreiro de neon","ru":"Неоновая вывеска"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: yukarı tırmanan synth arpeji ve elektrik uğultusu.","en":"A short sound everyone hears when you join a voice channel: a climbing synth arpeggio and an electric hum.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein aufsteigendes Synth-Arpeggio und elektrisches Summen.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un arpegio de sintetizador ascendente y un zumbido eléctrico.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un arpège de synthé qui monte et un bourdonnement électrique.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um arpejo de sintetizador subindo e um zumbido elétrico.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: восходящее синтезаторное арпеджио и электрический гул."}}'::jsonb, '["sound","set","length:1"]'::jsonb, '{"recipe":{"v":1,"dur":1,"gain":0.8,"echo":{"time":0.12,"fb":0.3,"mix":0.25},"voices":[{"type":"osc","w":"square","f":"E5","t":0,"d":0.09,"g":0.28,"env":{"a":0.002,"d":0.08},"filt":{"type":"lowpass","f":3200}},{"type":"osc","w":"square","f":"G#5","t":0.08,"d":0.09,"g":0.28,"env":{"a":0.002,"d":0.08},"filt":{"type":"lowpass","f":3200}},{"type":"osc","w":"square","f":"B5","t":0.16,"d":0.09,"g":0.28,"env":{"a":0.002,"d":0.08},"filt":{"type":"lowpass","f":3200}},{"type":"osc","w":"square","f":"E6","t":0.24,"d":0.32,"g":0.28,"env":{"a":0.002,"d":0.3},"filt":{"type":"lowpass","f":3600,"f2":1200}},{"type":"osc","w":"sawtooth","f":100,"t":0,"d":0.95,"g":0.14,"env":{"a":0.02,"d":0.4,"s":0.6,"r":0.3},"filt":{"type":"lowpass","f":420},"vib":{"r":12,"d":18}}]}}'::jsonb),
('s2-join_sound-altin-hasat', 'Harvest Flute', 'A short sound everyone hears when you join a voice channel: three warm notes from a breathy flute.', 'join_sound', 'data:,', NULL, 290, NULL, NULL, 'js-altin-hasat', 'rare', 106, 'altin-hasat', '{"name":{"tr":"Hasat Flütü","en":"Harvest Flute","de":"Ernteflöte","es":"Flauta de cosecha","fr":"Flûte des moissons","pt-BR":"Flauta da colheita","ru":"Флейта жатвы"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: nefesli bir flütten üç sıcak nota.","en":"A short sound everyone hears when you join a voice channel: three warm notes from a breathy flute.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: drei warme Töne einer hauchigen Flöte.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: tres notas cálidas de una flauta con aire.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : trois notes chaudes d''une flûte soufflée.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: três notas quentes de uma flauta soprada.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: три тёплые ноты воздушной флейты."}}'::jsonb, '["sound","set","length:1.4"]'::jsonb, '{"recipe":{"v":1,"dur":1.4,"gain":0.85,"echo":{"time":0.2,"fb":0.2,"mix":0.2},"voices":[{"type":"osc","w":"sine","f":"D5","t":0,"d":0.34,"g":0.5,"env":{"a":0.05,"d":0.34,"s":0.8,"r":0.12},"vib":{"r":5,"d":12}},{"type":"noise","col":"pink","t":0,"d":0.34,"g":0.06,"env":{"a":0.04,"d":0.34,"s":0.5,"r":0.1},"filt":{"type":"bandpass","f":"D5","q":3}},{"type":"osc","w":"sine","f":"E5","t":0.32,"d":0.3,"g":0.5,"env":{"a":0.05,"d":0.3,"s":0.8,"r":0.12},"vib":{"r":5,"d":12}},{"type":"noise","col":"pink","t":0.32,"d":0.3,"g":0.06,"env":{"a":0.04,"d":0.3,"s":0.5,"r":0.1},"filt":{"type":"bandpass","f":"E5","q":3}},{"type":"osc","w":"sine","f":"A5","t":0.6,"d":0.75,"g":0.5,"env":{"a":0.05,"d":0.75,"s":0.8,"r":0.12},"vib":{"r":5,"d":12}},{"type":"noise","col":"pink","t":0.6,"d":0.75,"g":0.06,"env":{"a":0.04,"d":0.75,"s":0.5,"r":0.1},"filt":{"type":"bandpass","f":"A5","q":3}}]}}'::jsonb),
('s2-join_sound-mor-sis', 'Haze Whisper', 'A short sound everyone hears when you join a voice channel: a soft chord that opens slowly.', 'join_sound', 'data:,', NULL, 300, NULL, NULL, 'js-mor-sis', 'rare', 107, 'mor-sis', '{"name":{"tr":"Sis Fısıltısı","en":"Haze Whisper","de":"Dunstflüstern","es":"Susurro de bruma","fr":"Murmure de brume","pt-BR":"Sussurro da névoa","ru":"Шёпот дымки"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: yavaşça açılan yumuşak bir akor.","en":"A short sound everyone hears when you join a voice channel: a soft chord that opens slowly.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein weicher Akkord, der sich langsam öffnet.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un acorde suave que se abre despacio.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un accord doux qui s''ouvre lentement.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um acorde suave que se abre devagar.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: мягкий аккорд, медленно раскрывающийся."}}'::jsonb, '["sound","set","length:1.45"]'::jsonb, '{"recipe":{"v":1,"dur":1.45,"gain":0.8,"echo":{"time":0.25,"fb":0.3,"mix":0.25},"voices":[{"type":"osc","w":"sawtooth","f":"D4","det":-8,"t":0,"d":1.4,"g":0.18,"pan":-0.4,"env":{"a":0.45,"d":0.4,"s":0.85,"r":0.45},"filt":{"type":"lowpass","f":500,"f2":2600,"q":1.2}},{"type":"osc","w":"sawtooth","f":"D4","det":8,"t":0.04,"d":1.3599999999999999,"g":0.18,"pan":0.4,"env":{"a":0.45,"d":0.4,"s":0.85,"r":0.45},"filt":{"type":"lowpass","f":500,"f2":2600,"q":1.2}},{"type":"osc","w":"sawtooth","f":"F4","det":0,"t":0.08,"d":1.3199999999999998,"g":0.18,"pan":-0.1,"env":{"a":0.45,"d":0.4,"s":0.85,"r":0.45},"filt":{"type":"lowpass","f":500,"f2":2600,"q":1.2}},{"type":"osc","w":"sawtooth","f":"A4","det":0,"t":0.12,"d":1.2799999999999998,"g":0.18,"pan":0.1,"env":{"a":0.45,"d":0.4,"s":0.85,"r":0.45},"filt":{"type":"lowpass","f":500,"f2":2600,"q":1.2}},{"type":"noise","col":"pink","t":0,"d":1.4,"g":0.07,"env":{"a":0.5,"d":0.5,"s":0.7,"r":0.4},"filt":{"type":"lowpass","f":1500}}]}}'::jsonb),
('s2-join_sound-gece-mercani', 'Coral Bubbles', 'A short sound everyone hears when you join a voice channel: playful bubbles rising through the water.', 'join_sound', 'data:,', NULL, 300, NULL, NULL, 'js-gece-mercani', 'rare', 108, 'gece-mercani', '{"name":{"tr":"Mercan Kabarcığı","en":"Coral Bubbles","de":"Korallenblasen","es":"Burbujas de coral","fr":"Bulles de corail","pt-BR":"Bolhas de coral","ru":"Коралловые пузырьки"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: suyun içinden yükselen tatlı kabarcıklar.","en":"A short sound everyone hears when you join a voice channel: playful bubbles rising through the water.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: verspielte Blasen, die durchs Wasser steigen.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: burbujas juguetonas que suben por el agua.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : des bulles joueuses qui remontent dans l''eau.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: bolhas brincalhonas subindo pela água.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: игривые пузырьки, поднимающиеся в воде."}}'::jsonb, '["sound","set","length:0.95"]'::jsonb, '{"recipe":{"v":1,"dur":0.95,"gain":0.85,"echo":{"time":0.1,"fb":0.2,"mix":0.2},"voices":[{"type":"osc","w":"sine","f":300,"f2":900,"gl":0.07,"t":0,"d":0.11,"g":0.5,"pan":-0.3,"env":{"a":0.003,"d":0.1}},{"type":"osc","w":"sine","f":420,"f2":1200,"gl":0.07,"t":0.14,"d":0.11,"g":0.5,"pan":0.3,"env":{"a":0.003,"d":0.1}},{"type":"osc","w":"sine","f":360,"f2":1000,"gl":0.07,"t":0.3,"d":0.11,"g":0.5,"pan":-0.1,"env":{"a":0.003,"d":0.1}},{"type":"osc","w":"sine","f":520,"f2":1500,"gl":0.07,"t":0.5,"d":0.11,"g":0.5,"pan":0.2,"env":{"a":0.003,"d":0.1}},{"type":"osc","w":"sine","f":"F2","t":0,"d":0.6,"g":0.2,"env":{"a":0.05,"d":0.5}}]}}'::jsonb),
('s2-join_sound-kuzey-isigi', 'Aurora Chord', 'A short sound everyone hears when you join a voice channel: a shimmering four-note chord.', 'join_sound', 'data:,', NULL, 330, NULL, NULL, 'js-kuzey-isigi', 'rare', 109, 'kuzey-isigi', '{"name":{"tr":"Aurora Akoru","en":"Aurora Chord","de":"Polarlichtakkord","es":"Acorde de aurora","fr":"Accord d''aurore","pt-BR":"Acorde da aurora","ru":"Аккорд сияния"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: titreşen dört notalık parlak bir akor.","en":"A short sound everyone hears when you join a voice channel: a shimmering four-note chord.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein schimmernder Vierklang.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un acorde brillante de cuatro notas.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un accord scintillant de quatre notes.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um acorde cintilante de quatro notas.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: мерцающий аккорд из четырёх нот."}}'::jsonb, '["sound","set","length:1.45"]'::jsonb, '{"recipe":{"v":1,"dur":1.45,"gain":0.8,"echo":{"time":0.3,"fb":0.35,"mix":0.3},"voices":[{"type":"osc","w":"triangle","f":"C5","t":0,"d":1.3,"g":0.26,"pan":-0.5,"env":{"a":0.08,"d":1.1},"vib":{"r":6,"d":10}},{"type":"osc","w":"triangle","f":"E5","t":0.05,"d":1.25,"g":0.26,"pan":-0.15,"env":{"a":0.08,"d":1.1},"vib":{"r":6,"d":10}},{"type":"osc","w":"triangle","f":"G5","t":0.1,"d":1.2,"g":0.26,"pan":0.15,"env":{"a":0.08,"d":1.1},"vib":{"r":6,"d":10}},{"type":"osc","w":"triangle","f":"B5","t":0.15000000000000002,"d":1.15,"g":0.26,"pan":0.5,"env":{"a":0.08,"d":1.1},"vib":{"r":6,"d":10}},{"type":"fm","f":"C7","ratio":3,"idx":0.5,"idxD":0.3,"t":0.3,"d":0.45,"g":0.12,"env":{"a":0.002,"d":0.4}}]}}'::jsonb),
('s2-join_sound-zumrut-orman', 'Forest Bird', 'A short sound everyone hears when you join a voice channel: quick bird chirps and two wooden knocks.', 'join_sound', 'data:,', NULL, 290, NULL, NULL, 'js-zumrut-orman', 'rare', 110, 'zumrut-orman', '{"name":{"tr":"Orman Kuşu","en":"Forest Bird","de":"Waldvogel","es":"Pájaro del bosque","fr":"Oiseau des bois","pt-BR":"Pássaro da floresta","ru":"Лесная птица"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: kısa kuş cıvıltıları ve iki tahta vuruşu.","en":"A short sound everyone hears when you join a voice channel: quick bird chirps and two wooden knocks.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: kurzes Vogelzwitschern und zwei Holzschläge.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: trinos rápidos y dos golpes de madera.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : de vifs gazouillis et deux coups de bois.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: piados rápidos e duas batidas de madeira.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: короткое щебетание и два деревянных стука."}}'::jsonb, '["sound","set","length:1.05"]'::jsonb, '{"recipe":{"v":1,"dur":1.05,"gain":0.8,"echo":{"time":0.15,"fb":0.2,"mix":0.2},"voices":[{"type":"osc","w":"sine","f":2800,"t":0,"d":0.07,"g":0.35,"env":{"a":0.003,"d":0.06300000000000001},"f2":4200,"gl":0.05,"pan":0.4},{"type":"osc","w":"sine","f":3000,"t":0.09,"d":0.07,"g":0.32,"env":{"a":0.003,"d":0.06300000000000001},"f2":4400,"gl":0.05,"pan":0.4},{"type":"osc","w":"sine","f":3400,"t":0.24,"d":0.1,"g":0.3,"env":{"a":0.003,"d":0.09000000000000001},"f2":2400,"gl":0.08,"pan":0.35},{"type":"osc","w":"sine","f":"C4","f2":"G3","gl":0.05,"t":0.48,"d":0.09,"g":0.55,"env":{"a":0.002,"d":0.08}},{"type":"osc","w":"sine","f":"E4","f2":"B3","gl":0.05,"t":0.6,"d":0.09,"g":0.5,"env":{"a":0.002,"d":0.08}},{"type":"nois