('s2-join_sound-kum-saati', 'Sand Flow', 'A short sound everyone hears when you join a voice channel: the hiss of flowing sand and a small bell.', 'join_sound', 'data:,', NULL, 280, NULL, NULL, 'js-kum-saati', 'rare', 111, 'kum-saati', '{"name":{"tr":"Kum Akışı","en":"Sand Flow","de":"Sandfluss","es":"Arena que fluye","fr":"Sable qui s''écoule","pt-BR":"Areia escorrendo","ru":"Течение песка"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: akan kumun hışırtısı ve küçük bir çan.","en":"A short sound everyone hears when you join a voice channel: the hiss of flowing sand and a small bell.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: das Rieseln von Sand und eine kleine Glocke.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: el siseo de la arena y una campanita.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : le chuintement du sable et une petite cloche.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: o chiado da areia e um sininho.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: шорох сыплющегося песка и маленький колокольчик."}}'::jsonb, '["sound","set","length:1.4"]'::jsonb, '{"recipe":{"v":1,"dur":1.4,"gain":0.8,"voices":[{"type":"noise","col":"white","t":0,"d":1,"g":0.28,"env":{"a":0.12,"d":0.6,"s":0.6,"r":0.3},"filt":{"type":"bandpass","f":4200,"f2":1800,"q":1.4}},{"type":"noise","col":"white","t":0,"d":0.02,"g":0.3,"env":{"a":0.001,"d":0.015},"filt":{"type":"highpass","f":5000}},{"type":"noise","col":"white","t":0.45,"d":0.02,"g":0.3,"env":{"a":0.001,"d":0.015},"filt":{"type":"highpass","f":5000}},{"type":"noise","col":"white","t":0.9,"d":0.02,"g":0.3,"env":{"a":0.001,"d":0.015},"filt":{"type":"highpass","f":5000}},{"type":"fm","f":"G5","t":0.85,"d":0.55,"g":0.3,"ratio":2,"idx":0.6,"idxD":0.385,"env":{"a":0.002,"d":0.49500000000000005}}]}}'::jsonb),
('s2-join_sound-firtina-cekirdegi', 'Distant Thunder', 'A short sound everyone hears when you join a voice channel: a deep rumble and a crack of electricity.', 'join_sound', 'data:,', NULL, 320, NULL, NULL, 'js-firtina-cekirdegi', 'rare', 112, 'firtina-cekirdegi', '{"name":{"tr":"Uzak Gök Gürültüsü","en":"Distant Thunder","de":"Fernes Donnern","es":"Trueno lejano","fr":"Tonnerre lointain","pt-BR":"Trovão distante","ru":"Далёкий гром"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: derin bir gürleme ve çakan bir elektrik.","en":"A short sound everyone hears when you join a voice channel: a deep rumble and a crack of electricity.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein tiefes Grollen und ein elektrischer Knall.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un retumbar profundo y un chasquido eléctrico.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un grondement profond et un claquement électrique.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um ronco profundo e um estalo elétrico.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: глубокий раскат и электрический треск."}}'::jsonb, '["sound","set","length:1.4"]'::jsonb, '{"recipe":{"v":1,"dur":1.4,"gain":0.85,"voices":[{"type":"noise","col":"brown","t":0,"d":1.35,"g":0.8,"env":{"a":0.06,"d":1.2},"filt":{"type":"lowpass","f":320}},{"type":"osc","w":"sawtooth","f":2000,"f2":200,"gl":0.25,"t":0.04,"d":0.3,"g":0.2,"env":{"a":0.002,"d":0.28},"filt":{"type":"lowpass","f":3000}},{"type":"noise","col":"white","t":0.02,"d":0.12,"g":0.3,"env":{"a":0.001,"d":0.1},"filt":{"type":"bandpass","f":3000,"q":1}}]}}'::jsonb),
('s2-join_sound-lav-akisi', 'Lava Bubble', 'A short sound everyone hears when you join a voice channel: thick, heavy bubbles and a sizzle.', 'join_sound', 'data:,', NULL, 320, NULL, NULL, 'js-lav-akisi', 'rare', 113, 'lav-akisi', '{"name":{"tr":"Lav Kabarcığı","en":"Lava Bubble","de":"Lavablase","es":"Burbuja de lava","fr":"Bulle de lave","pt-BR":"Bolha de lava","ru":"Пузырь лавы"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: kalın, ağır kabarcıklar ve cızırtı.","en":"A short sound everyone hears when you join a voice channel: thick, heavy bubbles and a sizzle.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: dicke, schwere Blasen und ein Zischen.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: burbujas espesas y pesadas y un chisporroteo.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : des bulles épaisses et lourdes et un grésillement.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: bolhas grossas e pesadas e um chiado.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: густые тяжёлые пузыри и шипение."}}'::jsonb, '["sound","set","length:1.1"]'::jsonb, '{"recipe":{"v":1,"dur":1.1,"gain":0.85,"voices":[{"type":"osc","w":"sine","f":90,"t":0,"d":0.26,"g":0.65,"env":{"a":0.003,"d":0.234},"f2":220,"gl":0.12},{"type":"osc","w":"sine","f":70,"t":0.3,"d":0.3,"g":0.55,"env":{"a":0.003,"d":0.27},"f2":180,"gl":0.14},{"type":"noise","col":"white","t":0.05,"d":0.95,"g":0.12,"env":{"a":0.05,"d":0.8},"filt":{"type":"highpass","f":3000}},{"type":"fm","f":"A2","ratio":0.5,"idx":2,"idxD":0.5,"t":0,"d":0.7,"g":0.25,"env":{"a":0.01,"d":0.6}}]}}'::jsonb),
('s2-join_sound-inci-kiyisi', 'Pearl Shell', 'A short sound everyone hears when you join a voice channel: a soft shell chime and the hush of foam.', 'join_sound', 'data:,', NULL, 300, NULL, NULL, 'js-inci-kiyisi', 'rare', 114, 'inci-kiyisi', '{"name":{"tr":"İnci Kabuğu","en":"Pearl Shell","de":"Perlmuschel","es":"Concha de perla","fr":"Coquille de perle","pt-BR":"Concha de pérola","ru":"Жемчужная раковина"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: yumuşak bir kabuk çanı ve köpük sesi.","en":"A short sound everyone hears when you join a voice channel: a soft shell chime and the hush of foam.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein sanfter Muschelklang und rauschender Schaum.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un suave tintineo de concha y el susurro de la espuma.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un doux tintement de coquillage et le souffle de l''écume.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um tilintar suave de concha e o sussurro da espuma.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: мягкий звон раковины и шелест пены."}}'::jsonb, '["sound","set","length:1.4"]'::jsonb, '{"recipe":{"v":1,"dur":1.4,"gain":0.8,"echo":{"time":0.2,"fb":0.3,"mix":0.25},"voices":[{"type":"fm","f":"G5","t":0,"d":1,"g":0.38,"ratio":1.5,"idx":1,"idxD":0.7,"env":{"a":0.002,"d":0.9}},{"type":"fm","f":"D6","t":0.12,"d":0.9,"g":0.26,"ratio":1.5,"idx":0.8,"idxD":0.63,"env":{"a":0.002,"d":0.81},"pan":0.3},{"type":"noise","col":"pink","t":0,"d":1.2,"g":0.13,"env":{"a":0.25,"d":0.7,"s":0.5,"r":0.4},"filt":{"type":"highpass","f":1500,"f2":6000}}]}}'::jsonb),
('s2-join_sound-yildiz-tozu', 'Star Sprinkle', 'A short sound everyone hears when you join a voice channel: glittering notes rising fast.', 'join_sound', 'data:,', NULL, 340, NULL, NULL, 'js-yildiz-tozu', 'rare', 115, 'yildiz-tozu', '{"name":{"tr":"Yıldız Serpintisi","en":"Star Sprinkle","de":"Sternenregen","es":"Lluvia de estrellas","fr":"Pluie d''étoiles","pt-BR":"Chuva de estrelas","ru":"Звёздная россыпь"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: hızla yükselen ışıltılı notalar.","en":"A short sound everyone hears when you join a voice channel: glittering notes rising fast.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: glitzernde Töne, die schnell aufsteigen.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: notas brillantes que suben rápido.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : des notes scintillantes qui montent vite.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: notas cintilantes subindo rápido.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: сверкающие ноты, быстро взлетающие вверх."}}'::jsonb, '["sound","set","length:1.45"]'::jsonb, '{"recipe":{"v":1,"dur":1.45,"gain":0.8,"echo":{"time":0.17,"fb":0.45,"mix":0.35},"voices":[{"type":"osc","w":"sine","f":"E6","t":0,"d":0.42,"g":0.22,"env":{"a":0.003,"d":0.378},"pan":-0.5},{"type":"osc","w":"sine","f":"G#6","t":0.06,"d":0.42,"g":0.22,"env":{"a":0.003,"d":0.378},"pan":-0.25},{"type":"osc","w":"sine","f":"B6","t":0.12,"d":0.42,"g":0.22,"env":{"a":0.003,"d":0.378},"pan":0},{"type":"osc","w":"sine","f":"E7","t":0.18,"d":0.42,"g":0.22,"env":{"a":0.003,"d":0.378},"pan":0.25},{"type":"osc","w":"sine","f":"G#7","t":0.24,"d":0.42,"g":0.22,"env":{"a":0.003,"d":0.378},"pan":0.5},{"type":"fm","f":"E5","ratio":4,"idx":0.4,"idxD":0.8,"t":0,"d":1,"g":0.2,"env":{"a":0.01,"d":0.9}},{"type":"noise","col":"white","t":0,"d":0.5,"g":0.06,"env":{"a":0.002,"d":0.45},"filt":{"type":"highpass","f":9000}}]}}'::jsonb),
('s2-join_sound-cam-can', 'Glass Bell', 'A short sound everyone hears when you join a voice channel: a single, clear strike of a glass bell.', 'join_sound', 'data:,', NULL, 360, NULL, NULL, 'js-cam-can', 'rare', 316, NULL, '{"name":{"tr":"Cam Çan","en":"Glass Bell","de":"Glasglocke","es":"Campana de cristal","fr":"Cloche de verre","pt-BR":"Sino de vidro","ru":"Стеклянный колокол"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: berrak ve tek bir cam çan vuruşu.","en":"A short sound everyone hears when you join a voice channel: a single, clear strike of a glass bell.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein einzelner, klarer Schlag einer Glasglocke.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un único golpe claro de campana de cristal.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un seul coup clair de cloche de verre.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: uma única batida clara de sino de vidro.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: один чистый удар стеклянного колокола."}}'::jsonb, '["sound","length:1.2"]'::jsonb, '{"recipe":{"v":1,"dur":1.2,"gain":0.8,"echo":{"time":0.2,"fb":0.3,"mix":0.25},"voices":[{"type":"fm","f":"C6","t":0,"d":1,"g":0.45,"ratio":3.01,"idx":2,"idxD":0.7,"env":{"a":0.002,"d":0.9}},{"type":"fm","f":"G6","t":0.08,"d":0.9,"g":0.25,"ratio":3.01,"idx":1.6,"idxD":0.63,"env":{"a":0.002,"d":0.81},"pan":0.3}]}}'::jsonb),
('s2-join_sound-kalimba-merhaba', 'Kalimba Hello', 'A short sound everyone hears when you join a voice channel: a cheerful four-note kalimba arpeggio.', 'join_sound', 'data:,', NULL, 420, NULL, NULL, 'js-kalimba-merhaba', 'rare', 317, NULL, '{"name":{"tr":"Kalimba Selamı","en":"Kalimba Hello","de":"Kalimba-Gruß","es":"Saludo de kalimba","fr":"Salut kalimba","pt-BR":"Olá de kalimba","ru":"Привет калимбы"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: dört notalık neşeli bir kalimba arpeji.","en":"A short sound everyone hears when you join a voice channel: a cheerful four-note kalimba arpeggio.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein fröhliches Kalimba-Arpeggio aus vier Tönen.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un alegre arpegio de kalimba de cuatro notas.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un joyeux arpège de kalimba en quatre notes.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um arpejo alegre de kalimba com quatro notas.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: весёлое арпеджио калимбы из четырёх нот."}}'::jsonb, '["sound","length:1"]'::jsonb, '{"recipe":{"v":1,"dur":1,"gain":0.85,"echo":{"time":0.16,"fb":0.2,"mix":0.18},"voices":[{"type":"fm","f":"G5","ratio":7,"idx":0.9,"idxD":0.05,"t":0,"d":0.5,"g":0.42,"pan":-0.3,"env":{"a":0.002,"d":0.45}},{"type":"fm","f":"B5","ratio":7,"idx":0.9,"idxD":0.05,"t":0.11,"d":0.5,"g":0.42,"pan":-0.09999999999999998,"env":{"a":0.002,"d":0.45}},{"type":"fm","f":"D6","ratio":7,"idx":0.9,"idxD":0.05,"t":0.22,"d":0.5,"g":0.42,"pan":0.10000000000000003,"env":{"a":0.002,"d":0.45}},{"type":"fm","f":"G6","ratio":7,"idx":0.9,"idxD":0.05,"t":0.33,"d":0.5,"g":0.42,"pan":0.3000000000000001,"env":{"a":0.002,"d":0.45}}]}}'::jsonb),
('s2-join_sound-neon-blip', 'Neon Blip', 'A short sound everyone hears when you join a voice channel: three short, lively digital blips.', 'join_sound', 'data:,', NULL, 180, NULL, NULL, 'js-neon-blip', 'common', 318, NULL, '{"name":{"tr":"Neon Blip","en":"Neon Blip","de":"Neon-Blip","es":"Blip de neón","fr":"Blip néon","pt-BR":"Blip neon","ru":"Неоновый блип"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: kısa ve canlı üç dijital bip.","en":"A short sound everyone hears when you join a voice channel: three short, lively digital blips.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: drei kurze, lebhafte Digitaltöne.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: tres pitidos digitales cortos y vivos.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : trois bips numériques courts et vifs.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: três bipes digitais curtos e animados.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: три коротких бодрых цифровых сигнала."}}'::jsonb, '["sound","length:0.55"]'::jsonb, '{"recipe":{"v":1,"dur":0.55,"gain":0.8,"voices":[{"type":"osc","w":"square","f":"C5","f2":"C6","gl":0.06,"t":0,"d":0.1,"g":0.3,"env":{"a":0.002,"d":0.09},"filt":{"type":"lowpass","f":2500}},{"type":"osc","w":"square","f":"G5","t":0.1,"d":0.08,"g":0.28,"env":{"a":0.002,"d":0.07},"filt":{"type":"lowpass","f":2500}},{"type":"osc","w":"square","f":"C6","t":0.19,"d":0.18,"g":0.28,"env":{"a":0.002,"d":0.16},"filt":{"type":"lowpass","f":2800,"f2":900}}]}}'::jsonb),
('s2-join_sound-kapi-tiki', 'Door Knock', 'A short sound everyone hears when you join a voice channel: two polite knocks and a little chime.', 'join_sound', 'data:,', NULL, 160, NULL, NULL, 'js-kapi-tiki', 'common', 319, NULL, '{"name":{"tr":"Kapı Tıkı","en":"Door Knock","de":"Türklopfen","es":"Toc en la puerta","fr":"Toc toc","pt-BR":"Toque na porta","ru":"Стук в дверь"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: iki kibar tıklatma ve küçük bir çan.","en":"A short sound everyone hears when you join a voice channel: two polite knocks and a little chime.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: zweimal höflich klopfen und ein kleiner Klang.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: dos toques educados y una campanita.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : deux coups polis et un petit carillon.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: duas batidas educadas e um sininho.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: два вежливых стука и маленький звонок."}}'::jsonb, '["sound","length:1"]'::jsonb, '{"recipe":{"v":1,"dur":1,"gain":0.85,"voices":[{"type":"osc","w":"sine","f":"A3","f2":"E3","gl":0.05,"t":0,"d":0.08,"g":0.7,"env":{"a":0.001,"d":0.07}},{"type":"noise","col":"white","t":0,"d":0.03,"g":0.25,"env":{"a":0.001,"d":0.025},"filt":{"type":"lowpass","f":1200}},{"type":"osc","w":"sine","f":"A3","f2":"E3","gl":0.05,"t":0.13,"d":0.08,"g":0.7,"env":{"a":0.001,"d":0.07}},{"type":"noise","col":"white","t":0.13,"d":0.03,"g":0.25,"env":{"a":0.001,"d":0.025},"filt":{"type":"lowpass","f":1200}},{"type":"fm","f":"E5","t":0.3,"d":0.65,"g":0.3,"ratio":2,"idx":0.8,"idxD":0.45499999999999996,"env":{"a":0.002,"d":0.5850000000000001}}]}}'::jsonb),
('s2-join_sound-su-damlasi', 'Water Drop', 'A short sound everyone hears when you join a voice channel: a single echoing drop of water.', 'join_sound', 'data:,', NULL, 150, NULL, NULL, 'js-su-damlasi', 'common', 320, NULL, '{"name":{"tr":"Su Damlası","en":"Water Drop","de":"Wassertropfen","es":"Gota de agua","fr":"Goutte d''eau","pt-BR":"Gota d''água","ru":"Капля воды"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: yankılanan tek bir su damlası.","en":"A short sound everyone hears when you join a voice channel: a single echoing drop of water.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein einzelner Wassertropfen mit Echo.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: una sola gota de agua con eco.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : une seule goutte d''eau qui résonne.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: uma única gota d''água ecoando.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: одна звонкая капля с эхом."}}'::jsonb, '["sound","length:0.8"]'::jsonb, '{"recipe":{"v":1,"dur":0.8,"gain":0.8,"echo":{"time":0.12,"fb":0.35,"mix":0.35},"voices":[{"type":"osc","w":"sine","f":600,"t":0,"d":0.13,"g":0.7,"env":{"a":0.002,"d":0.12},"f2":1800,"gl":0.04}]}}'::jsonb),
('s2-join_sound-ud-teli', 'Oud String', 'A short sound everyone hears when you join a voice channel: three warm plucked tones rising up.', 'join_sound', 'data:,', NULL, 460, NULL, NULL, 'js-ud-teli', 'rare', 321, NULL, '{"name":{"tr":"Ud Teli","en":"Oud String","de":"Oud-Saite","es":"Cuerda de laúd","fr":"Corde d''oud","pt-BR":"Corda de alaúde","ru":"Струна уда"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: tellerden yükselen üç sıcak tını.","en":"A short sound everyone hears when you join a voice channel: three warm plucked tones rising up.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: drei warme, gezupfte Töne, die aufsteigen.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: tres cálidos tonos pulsados que suben.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : trois notes pincées et chaudes qui montent.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: três notas dedilhadas e quentes subindo.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: три тёплых щипковых звука, идущих вверх."}}'::jsonb, '["sound","length:1.3"]'::jsonb, '{"recipe":{"v":1,"dur":1.3,"gain":0.85,"echo":{"time":0.18,"fb":0.2,"mix":0.15},"voices":[{"type":"pluck","f":"D3","t":0,"d":1.2,"g":0.6,"env":{"a":0.002,"d":1},"pan":-0.2},{"type":"pluck","f":"A3","t":0.14,"d":1,"g":0.5,"env":{"a":0.002,"d":0.85}},{"type":"pluck","f":"D4","t":0.28,"d":1,"g":0.45,"env":{"a":0.002,"d":0.85},"pan":0.2}]}}'::jsonb),
('s2-join_sound-marimba-selami', 'Marimba Greeting', 'A short sound everyone hears when you join a voice channel: a chord climbing up wooden keys.', 'join_sound', 'data:,', NULL, 380, NULL, NULL, 'js-marimba-selami', 'rare', 322, NULL, '{"name":{"tr":"Marimba Selamı","en":"Marimba Greeting","de":"Marimba-Gruß","es":"Saludo de marimba","fr":"Salut marimba","pt-BR":"Saudação de marimba","ru":"Приветствие маримбы"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: ahşap tuşlardan yükselen bir akor.","en":"A short sound everyone hears when you join a voice channel: a chord climbing up wooden keys.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein Akkord, der über Holztasten steigt.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un acorde que sube por teclas de madera.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un accord qui grimpe sur des lames de bois.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um acorde subindo por teclas de madeira.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: аккорд, поднимающийся по деревянным пластинам."}}'::jsonb, '["sound","length:0.95"]'::jsonb, '{"recipe":{"v":1,"dur":0.95,"gain":0.85,"voices":[{"type":"fm","f":"C5","ratio":4,"idx":0.35,"idxD":0.05,"t":0,"d":0.5,"g":0.45,"pan":-0.3,"env":{"a":0.002,"d":0.4}},{"type":"fm","f":"E5","ratio":4,"idx":0.35,"idxD":0.05,"t":0.1,"d":0.5,"g":0.45,"pan":-0.09999999999999998,"env":{"a":0.002,"d":0.4}},{"type":"fm","f":"G5","ratio":4,"idx":0.35,"idxD":0.05,"t":0.2,"d":0.5,"g":0.45,"pan":0.10000000000000003,"env":{"a":0.002,"d":0.4}},{"type":"fm","f":"C6","ratio":4,"idx":0.35,"idxD":0.05,"t":0.30000000000000004,"d":0.5,"g":0.45,"pan":0.3000000000000001,"env":{"a":0.002,"d":0.4}}]}}'::jsonb),
('s2-join_sound-kus-civiltisi', 'Birdsong', 'A short sound everyone hears when you join a voice channel: a short and cheerful chirp.', 'join_sound', 'data:,', NULL, 340, NULL, NULL, 'js-kus-civiltisi', 'rare', 323, NULL, '{"name":{"tr":"Kuş Cıvıltısı","en":"Birdsong","de":"Vogelgezwitscher","es":"Canto de pájaro","fr":"Chant d''oiseau","pt-BR":"Canto de pássaro","ru":"Птичья трель"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: neşeli ve kısa bir kuş cıvıltısı.","en":"A short sound everyone hears when you join a voice channel: a short and cheerful chirp.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein kurzes, fröhliches Zwitschern.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un trino corto y alegre.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un gazouillis court et joyeux.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um piado curto e alegre.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: короткая весёлая трель."}}'::jsonb, '["sound","length:0.9"]'::jsonb, '{"recipe":{"v":1,"dur":0.9,"gain":0.8,"echo":{"time":0.11,"fb":0.2,"mix":0.18},"voices":[{"type":"osc","w":"sine","f":2600,"t":0,"d":0.07,"g":0.35,"env":{"a":0.003,"d":0.06300000000000001},"f2":4000,"gl":0.05,"pan":-0.3},{"type":"osc","w":"sine","f":2800,"t":0.08,"d":0.07,"g":0.35,"env":{"a":0.003,"d":0.06300000000000001},"f2":4300,"gl":0.05,"pan":0.3},{"type":"osc","w":"sine","f":3000,"t":0.16,"d":0.07,"g":0.35,"env":{"a":0.003,"d":0.06300000000000001},"f2":4500,"gl":0.05,"pan":-0.3},{"type":"osc","w":"sine","f":4200,"t":0.34,"d":0.07,"g":0.35,"env":{"a":0.003,"d":0.06300000000000001},"f2":2600,"gl":0.05,"pan":0.3},{"type":"osc","w":"sine","f":3600,"t":0.5,"d":0.07,"g":0.35,"env":{"a":0.003,"d":0.06300000000000001},"f2":5000,"gl":0.05,"pan":-0.3}]}}'::jsonb),
('s2-join_sound-lazer-halka', 'Laser Ring', 'A short sound everyone hears when you join a voice channel: a laser sweep falling down with an echo.', 'join_sound', 'data:,', NULL, 320, NULL, NULL, 'js-lazer-halka', 'rare', 324, NULL, '{"name":{"tr":"Lazer Halka","en":"Laser Ring","de":"Laserring","es":"Anillo láser","fr":"Anneau laser","pt-BR":"Anel de laser","ru":"Лазерное кольцо"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: aşağı süzülen yankılı bir lazer.","en":"A short sound everyone hears when you join a voice channel: a laser sweep falling down with an echo.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein abfallender Laser-Sweep mit Echo.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un barrido láser que cae con eco.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un balayage laser qui descend avec écho.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um laser descendo com eco.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: нисходящий лазерный свип с эхом."}}'::jsonb, '["sound","length:0.9"]'::jsonb, '{"recipe":{"v":1,"dur":0.9,"gain":0.8,"echo":{"time":0.09,"fb":0.4,"mix":0.3},"voices":[{"type":"osc","w":"sawtooth","f":3000,"f2":300,"gl":0.35,"t":0,"d":0.4,"g":0.35,"env":{"a":0.002,"d":0.38},"filt":{"type":"lowpass","f":4000,"f2":800,"q":8}}]}}'::jsonb),
('s2-join_sound-uzay-kapisi', 'Space Gate', 'A short sound everyone hears when you join a voice channel: the whoosh and sparkle of a gate opening.', 'join_sound', 'data:,', NULL, 680, NULL, NULL, 'js-uzay-kapisi', 'epic', 325, NULL, '{"name":{"tr":"Uzay Kapısı","en":"Space Gate","de":"Raumtor","es":"Portal espacial","fr":"Porte spatiale","pt-BR":"Portal espacial","ru":"Космические врата"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: açılan bir geçidin uğultusu ve ışıltısı.","en":"A short sound everyone hears when you join a voice channel: the whoosh and sparkle of a gate opening.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: das Rauschen und Funkeln eines sich öffnenden Tors.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: el silbido y destello de un portal que se abre.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : le souffle et l''éclat d''une porte qui s''ouvre.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: o sopro e o brilho de um portal se abrindo.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: гул и искры открывающихся врат."}}'::jsonb, '["sound","length:1.45"]'::jsonb, '{"recipe":{"v":1,"dur":1.45,"gain":0.85,"echo":{"time":0.2,"fb":0.3,"mix":0.25},"voices":[{"type":"noise","col":"pink","t":0,"d":0.9,"g":0.5,"env":{"a":0.35,"d":0.5},"filt":{"type":"bandpass","f":300,"f2":3000,"q":4}},{"type":"osc","w":"sine","f":"C2","t":0,"d":0.9,"g":0.42,"env":{"a":0.2,"d":0.7},"f2":"C3","gl":0.6},{"type":"osc","w":"sine","f":"C7","t":0.55,"d":0.45,"g":0.14,"env":{"a":0.003,"d":0.405},"pan":0.3},{"type":"osc","w":"sine","f":"G6","t":0.62,"d":0.45,"g":0.1,"env":{"a":0.003,"d":0.405},"pan":-0.3}]}}'::jsonb);
INSERT INTO _shop2_seed (sku, name, description, category, asset_url, preview_url, price_descoin, theme_key, badge_icon, effect_key, rarity, sort_order, set_key, i18n, tags, meta) VALUES
('s2-join_sound-gong-esintisi', 'Gong Breeze', 'A short sound everyone hears when you join a voice channel: a small gong, deep and long-breathing.', 'join_sound', 'data:,', NULL, 620, NULL, NULL, 'js-gong-esintisi', 'epic', 326, NULL, '{"name":{"tr":"Gong Esintisi","en":"Gong Breeze","de":"Gongbrise","es":"Brisa de gong","fr":"Brise de gong","pt-BR":"Brisa de gongo","ru":"Дыхание гонга"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: derin ve uzun soluklu küçük bir gong.","en":"A short sound everyone hears when you join a voice channel: a small gong, deep and long-breathing.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein kleiner Gong, tief und lang ausklingend.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un pequeño gong, profundo y largo.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un petit gong, profond et long.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um pequeno gongo, profundo e longo.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: небольшой гонг, глубокий и протяжный."}}'::jsonb, '["sound","length:1.5"]'::jsonb, '{"recipe":{"v":1,"dur":1.5,"gain":0.85,"voices":[{"type":"fm","f":"A2","ratio":1.41,"idx":4,"idxD":1.2,"t":0,"d":1.48,"g":0.6,"env":{"a":0.003,"d":1.4}},{"type":"fm","f":"E3","ratio":2.1,"idx":2,"idxD":1,"t":0,"d":1.3,"g":0.25,"env":{"a":0.003,"d":1.2},"pan":0.2},{"type":"noise","col":"pink","t":0,"d":0.3,"g":0.12,"env":{"a":0.002,"d":0.25},"filt":{"type":"lowpass","f":2000}}]}}'::jsonb),
('s2-join_sound-ruzgar-cani', 'Wind Chimes', 'A short sound everyone hears when you join a voice channel: thin chimes touching each other in the breeze.', 'join_sound', 'data:,', NULL, 720, NULL, NULL, 'js-ruzgar-cani', 'epic', 327, NULL, '{"name":{"tr":"Rüzgar Çanı","en":"Wind Chimes","de":"Windspiel","es":"Carillón de viento","fr":"Carillon à vent","pt-BR":"Sino dos ventos","ru":"Музыка ветра"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: esintiyle birbirine değen ince çanlar.","en":"A short sound everyone hears when you join a voice channel: thin chimes touching each other in the breeze.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: feine Röhren, die sich im Wind berühren.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: finas campanas que se tocan con la brisa.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : de fins tubes qui se touchent dans la brise.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: sininhos finos se tocando na brisa.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: тонкие трубочки, касающиеся друг друга на ветру."}}'::jsonb, '["sound","length:1.4"]'::jsonb, '{"recipe":{"v":1,"dur":1.4,"gain":0.8,"echo":{"time":0.21,"fb":0.3,"mix":0.25},"voices":[{"type":"fm","f":"D6","t":0,"d":0.75,"g":0.24,"ratio":3.2,"idx":1,"idxD":0.5249999999999999,"env":{"a":0.002,"d":0.675},"pan":-0.6},{"type":"fm","f":"E6","t":0.09,"d":0.75,"g":0.24,"ratio":3.2,"idx":1,"idxD":0.5249999999999999,"env":{"a":0.002,"d":0.675},"pan":0.4},{"type":"fm","f":"G6","t":0.17,"d":0.75,"g":0.24,"ratio":3.2,"idx":1,"idxD":0.5249999999999999,"env":{"a":0.002,"d":0.675},"pan":-0.2},{"type":"fm","f":"A6","t":0.3,"d":0.75,"g":0.24,"ratio":3.2,"idx":1,"idxD":0.5249999999999999,"env":{"a":0.002,"d":0.675},"pan":0.6},{"type":"fm","f":"B6","t":0.41,"d":0.75,"g":0.24,"ratio":3.2,"idx":1,"idxD":0.5249999999999999,"env":{"a":0.002,"d":0.675},"pan":-0.4},{"type":"fm","f":"D7","t":0.55,"d":0.75,"g":0.24,"ratio":3.2,"idx":1,"idxD":0.5249999999999999,"env":{"a":0.002,"d":0.675},"pan":0.2},{"type":"noise","col":"pink","t":0,"d":1.35,"g":0.06,"env":{"a":0.3,"d":0.6,"s":0.5,"r":0.4},"filt":{"type":"bandpass","f":800,"q":0.8}}]}}'::jsonb),
('s2-join_sound-bas-darbesi', 'Bass Drop', 'A short sound everyone hears when you join a voice channel: a short, punchy and deep hit.', 'join_sound', 'data:,', NULL, 220, NULL, NULL, 'js-bas-darbesi', 'common', 328, NULL, '{"name":{"tr":"Bas Darbesi","en":"Bass Drop","de":"Bassschlag","es":"Golpe de bajo","fr":"Coup de basse","pt-BR":"Batida grave","ru":"Басовый удар"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: kısa, tok ve derin bir vuruş.","en":"A short sound everyone hears when you join a voice channel: a short, punchy and deep hit.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein kurzer, satter und tiefer Schlag.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un golpe corto, contundente y grave.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un coup court, sourd et profond.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: uma batida curta, encorpada e grave.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: короткий, плотный и глубокий удар."}}'::jsonb, '["sound","length:0.6"]'::jsonb, '{"recipe":{"v":1,"dur":0.6,"gain":0.9,"voices":[{"type":"osc","w":"sine","f":150,"t":0,"d":0.36,"g":0.9,"env":{"a":0.001,"d":0.34},"f2":45,"gl":0.12},{"type":"noise","col":"white","t":0,"d":0.012,"g":0.3,"env":{"a":0.001,"d":0.01},"filt":{"type":"lowpass","f":4000}},{"type":"osc","w":"sine","f":"A1","t":0,"d":0.5,"g":0.3,"env":{"a":0.01,"d":0.45}}]}}'::jsonb),
('s2-join_sound-org-akoru', 'Organ Chord', 'A short sound everyone hears when you join a voice channel: a warm, wide organ chord.', 'join_sound', 'data:,', NULL, 580, NULL, NULL, 'js-org-akoru', 'epic', 329, NULL, '{"name":{"tr":"Org Akoru","en":"Organ Chord","de":"Orgelakkord","es":"Acorde de órgano","fr":"Accord d''orgue","pt-BR":"Acorde de órgão","ru":"Органный аккорд"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: sıcak ve geniş bir org akoru.","en":"A short sound everyone hears when you join a voice channel: a warm, wide organ chord.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein warmer, breiter Orgelakkord.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un acorde de órgano cálido y amplio.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un accord d''orgue chaud et ample.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um acorde de órgão quente e amplo.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: тёплый широкий органный аккорд."}}'::jsonb, '["sound","length:1.4"]'::jsonb, '{"recipe":{"v":1,"dur":1.4,"gain":0.8,"echo":{"time":0.18,"fb":0.25,"mix":0.2},"voices":[{"type":"osc","w":"sine","f":"C4","t":0,"d":1.35,"g":0.26,"pan":-0.3,"env":{"a":0.08,"d":0.3,"s":0.85,"r":0.35},"vib":{"r":5.5,"d":6}},{"type":"osc","w":"sine","f":"C4","det":1200,"t":0,"d":1.35,"g":0.08,"env":{"a":0.08,"d":0.3,"s":0.85,"r":0.35}},{"type":"osc","w":"sine","f":"E4","t":0,"d":1.35,"g":0.26,"pan":-0.09999999999999998,"env":{"a":0.08,"d":0.3,"s":0.85,"r":0.35},"vib":{"r":5.5,"d":6}},{"type":"osc","w":"sine","f":"E4","det":1200,"t":0,"d":1.35,"g":0.08,"env":{"a":0.08,"d":0.3,"s":0.85,"r":0.35}},{"type":"osc","w":"sine","f":"G4","t":0,"d":1.35,"g":0.26,"pan":0.10000000000000003,"env":{"a":0.08,"d":0.3,"s":0.85,"r":0.35},"vib":{"r":5.5,"d":6}},{"type":"osc","w":"sine","f":"G4","det":1200,"t":0,"d":1.35,"g":0.08,"env":{"a":0.08,"d":0.3,"s":0.85,"r":0.35}},{"type":"osc","w":"sine","f":"C5","t":0,"d":1.35,"g":0.26,"pan":0.3000000000000001,"env":{"a":0.08,"d":0.3,"s":0.85,"r":0.35},"vib":{"r":5.5,"d":6}},{"type":"osc","w":"sine","f":"C5","det":1200,"t":0,"d":1.35,"g":0.08,"env":{"a":0.08,"d":0.3,"s":0.85,"r":0.35}}]}}'::jsonb),
('s2-join_sound-yildiz-kaymasi', 'Shooting Star', 'A short sound everyone hears when you join a voice channel: a glittering glide sweeping up the sky.', 'join_sound', 'data:,', NULL, 980, NULL, NULL, 'js-yildiz-kaymasi', 'legendary', 330, NULL, '{"name":{"tr":"Yıldız Kayması","en":"Shooting Star","de":"Sternschnuppe","es":"Estrella fugaz","fr":"Étoile filante","pt-BR":"Estrela cadente","ru":"Падающая звезда"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: gökyüzünü yukarı tarayan ışıltılı bir kayış.","en":"A short sound everyone hears when you join a voice channel: a glittering glide sweeping up the sky.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: ein glitzerndes Gleiten den Himmel hinauf.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: un deslizamiento brillante que sube por el cielo.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : un glissement scintillant qui balaie le ciel.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: um deslize cintilante subindo pelo céu.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: сверкающий взлёт через всё небо."}}'::jsonb, '["sound","length:1.45"]'::jsonb, '{"recipe":{"v":1,"dur":1.45,"gain":0.8,"echo":{"time":0.2,"fb":0.45,"mix":0.35},"voices":[{"type":"osc","w":"sine","f":"G5","t":0,"d":0.7,"g":0.28,"env":{"a":0.01,"d":0.65},"f2":"G7","gl":0.6,"pan":-0.4},{"type":"fm","f":"D7","ratio":3,"idx":0.5,"idxD":0.2,"t":0.55,"d":0.5,"g":0.16,"pan":0.2,"env":{"a":0.002,"d":0.45}},{"type":"fm","f":"G7","ratio":3,"idx":0.5,"idxD":0.2,"t":0.6200000000000001,"d":0.5,"g":0.16,"pan":0.35,"env":{"a":0.002,"d":0.45}},{"type":"fm","f":"B7","ratio":3,"idx":0.5,"idxD":0.2,"t":0.6900000000000001,"d":0.5,"g":0.16,"pan":0.5,"env":{"a":0.002,"d":0.45}},{"type":"noise","col":"white","t":0.1,"d":0.7,"g":0.05,"env":{"a":0.3,"d":0.4},"filt":{"type":"highpass","f":9000}}]}}'::jsonb),
('s2-join_sound-saray-fanfari', 'Palace Fanfare', 'A short sound everyone hears when you join a voice channel: a short brass fanfare that announces you.', 'join_sound', 'data:,', NULL, 1150, NULL, NULL, 'js-saray-fanfari', 'legendary', 331, NULL, '{"name":{"tr":"Saray Fanfarı","en":"Palace Fanfare","de":"Palastfanfare","es":"Fanfarria de palacio","fr":"Fanfare du palais","pt-BR":"Fanfarra do palácio","ru":"Дворцовые фанфары"},"description":{"tr":"Bir ses kanalına girdiğinde herkesin duyduğu kısa ses: girişini duyuran kısa bir boru fanfarı.","en":"A short sound everyone hears when you join a voice channel: a short brass fanfare that announces you.","de":"Ein kurzer Klang, den alle hören, wenn du einem Sprachkanal beitrittst: eine kurze Blechbläserfanfare, die dich ankündigt.","es":"Un sonido breve que todos oyen cuando entras en un canal de voz: una breve fanfarria de metales que te anuncia.","fr":"Un court son que tout le monde entend quand tu rejoins un salon vocal : une courte fanfare de cuivres qui t''annonce.","pt-BR":"Um som curto que todos ouvem quando você entra em um canal de voz: uma curta fanfarra de metais que anuncia você.","ru":"Короткий звук, который слышат все, когда вы заходите в голосовой канал: короткие медные фанфары, объявляющие ваш приход."}}'::jsonb, '["sound","length:1.05"]'::jsonb, '{"recipe":{"v":1,"dur":1.05,"gain":0.85,"echo":{"time":0.16,"fb":0.2,"mix":0.18},"voices":[{"type":"osc","w":"sawtooth","f":"C4","t":0,"d":0.15,"g":0.32,"env":{"a":0.03,"d":0.1,"s":0.8,"r":0.1},"filt":{"type":"lowpass","f":700,"f2":2600,"ft":0.08,"q":1.5},"vib":{"r":5,"d":0}},{"type":"osc","w":"sawtooth","f":"C4","det":1205,"t":0,"d":0.15,"g":0.12,"env":{"a":0.03,"d":0.1,"s":0.8,"r":0.1},"filt":{"type":"lowpass","f":1200,"f2":3400,"ft":0.08}},{"type":"osc","w":"sawtooth","f":"C4","t":0.17,"d":0.12,"g":0.32,"env":{"a":0.03,"d":0.1,"s":0.8,"r":0.1},"filt":{"type":"lowpass","f":700,"f2":2600,"ft":0.08,"q":1.5},"vib":{"r":5,"d":0}},{"type":"osc","w":"sawtooth","f":"C4","det":1205,"t":0.17,"d":0.12,"g":0.12,"env":{"a":0.03,"d":0.1,"s":0.8,"r":0.1},"filt":{"type":"lowpass","f":1200,"f2":3400,"ft":0.08}},{"type":"osc","w":"sawtooth","f":"G4","t":0.31,"d":0.7,"g":0.32,"env":{"a":0.03,"d":0.1,"s":0.8,"r":0.1},"filt":{"type":"lowpass","f":700,"f2":2600,"ft":0.08,"q":1.5},"vib":{"r":5,"d":10}},{"type":"osc","w":"sawtooth","f":"G4","det":1205,"t":0.31,"d":0.7,"g":0.12,"env":{"a":0.03,"d":0.1,"s":0.8,"r":0.1},"filt":{"type":"lowpass","f":1200,"f2":3400,"ft":0.08}},{"type":"osc","w":"sine","f":"C3","t":0.31,"d":0.5,"g":0.4,"env":{"a":0.002,"d":0.45},"f2":"C2","gl":0.3}]}}'::jsonb);
